/* GENERATED BY DEFAULT no adelanta el contador cuando el ID se da a mano: sin
   esto la primera categoria que se registre pediria el 1 y chocaria.

   El COMMIT de arriba no sobra: un ALTER sobre una tabla con inserciones sin
   confirmar muere con "object TABLE is in use", y el fallo deja al motor en
   bugcheck y la base inservible. */
COMMIT;
