  ELSE IF (UPDATING) THEN BEGIN V_ACCION = 'actualizar'; V_ID = NEW.USUARIO_ID; END
  ELSE BEGIN V_ACCION = 'borrar'; V_ID = OLD.USUARIO_ID; END
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'USUARIOS_CLAVES', :V_ID, 'cambio de clave');
END^

