/* ----------------------------------------------------------------------------
   Tablas que NO se auditan, y por que:

   AUDITORIA            se auditaria a si misma
   SOLICITUD_ADJUNTOS   croquis y fotos; el alta ya queda por SOLICITUDES
   SOLICITUD_MEDIDAS    idem
   COTIZACION_DETALLE   las lineas cambian mucho; lo que importa es el estado
                        de la cotizacion, que si se audita
   ROLES, MANO_OBRA_CATEGORIA, TIPOS_TRABAJO   catalogos cerrados
   MATERIALES, MANO_OBRA, MAQUINAS             lo sensible es el precio, no el
                                               nombre del articulo
---------------------------------------------------------------------------- */

/* ############################################################################
   TRAMO 04_usuario.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Usuario de conexion del backend  (Firebird)
   ----------------------------------------------------------------------------
   El backend NO se conecta como SYSDBA, por lo mismo que no se conectaba como
   'sa' en SQL Server: es el superusuario y anula cualquier control.

   ANOVO_BACKEND puede leer y escribir las tablas de negocio, y sobre AUDITORIA
   no puede nada: ahi solo escribe el disparador, que corre con los privilegios
   del dueno de la tabla y no con los del usuario.

   La clave va en el .env del servidor, nunca en este archivo ni en el
   repositorio. Antes de correrlo, sustituir CLAVE_PENDIENTE.
   ============================================================================ */

COMMIT;

CREATE ROLE ROL_BACKEND;
COMMIT;

/* Lectura y escritura sobre las tablas de negocio */
GRANT SELECT, INSERT, UPDATE, DELETE ON USUARIOS                        TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON USUARIOS_CLAVES                 TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON EMPRESA                         TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON CLIENTES                        TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON CLIENTE_CONTACTOS               TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON CLIENTE_CONSENTIMIENTO_HISTORIAL TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON SOLICITUDES                     TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON SOLICITUD_ADJUNTOS              TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON SOLICITUD_MEDIDAS               TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON MATERIALES                      TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON MATERIALES_PRECIOS              TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON MANO_OBRA                       TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON MANO_OBRA_PRECIOS               TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON MAQUINAS                        TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON MAQUINAS_PRECIOS                TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON COTIZACIONES                    TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE, DELETE ON COTIZACION_DETALLE              TO ROL_BACKEND;

/* Catalogos cerrados: solo lectura desde la aplicacion */
GRANT SELECT ON ROLES               TO ROL_BACKEND;
GRANT SELECT ON MANO_OBRA_CATEGORIA TO ROL_BACKEND;
GRANT SELECT, INSERT, UPDATE ON TIPOS_TRABAJO TO ROL_BACKEND;

/* AUDITORIA: solo lectura. La escritura es del disparador.
   Sin INSERT aqui, nadie puede fabricar ni adulterar un registro de auditoria
   desde la aplicacion, y sin DELETE nadie puede borrar el rastro. */
GRANT SELECT ON AUDITORIA TO ROL_BACKEND;

/* El generador del consecutivo de cotizaciones */
GRANT USAGE ON SEQUENCE GEN_COTIZACION_NUMERO TO ROL_BACKEND;

GRANT ROL_BACKEND TO ANOVO_BACKEND;

COMMIT;

/* ############################################################################
   TRAMO 05_permisos_disparadores.sql
   ############################################################################ */

/* ============================================================================
   PERMISO DE ESCRITURA PARA LOS DISPARADORES DE AUDITORIA
   Firebird 4.0 - base ANOVO
   15 de septiembre de 2026

   Por que hace falta.

   04_usuario.sql le da a ROL_BACKEND solo SELECT sobre AUDITORIA, con el
   razonamiento de que la escritura la hace el disparador y el disparador corre
   con los privilegios del dueno de la tabla. Esa segunda parte es falsa en
   Firebird 4: salvo que se diga lo contrario, las rutinas y los disparadores
   corren como SQL SECURITY INVOKER, o sea con los privilegios de quien invoca.
   Quien invoca es ANOVO_BACKEND, que no tiene ninguno sobre AUDITORIA.

   El sintoma es un INSERT de negocio que muere con
   "no permission for INSERT access to TABLE AUDITORIA", como si el problema lo
   tuviera la aplicacion, cuando lo tiene el disparador.

   Por que asi y no de otra forma.

   La alternativa seria GRANT INSERT ON AUDITORIA TO ROL_BACKEND, y eso echaria
   abajo lo que el diseno buscaba: si la aplicacion puede insertar en AUDITORIA,
   tambien puede fabricar registros de auditoria, y entonces la auditoria deja
   de probar nada.

   Concediendoselo al disparador, el permiso lo tiene el objeto y no el usuario:
   ANOVO_BACKEND sigue sin poder tocar AUDITORIA por su cuenta -ni con un INSERT
   directo, ni con UPDATE, ni con DELETE- y la unica via de escritura sigue
   siendo el disparador, que la base dispara sola y nadie puede saltarse.

   La otra alternativa, ALTER TRIGGER ... SQL SECURITY DEFINER, tambien
   funcionaria, pero le daria al disparador todos los privilegios del dueno de
   la base en vez del unico que necesita.
   ============================================================================ */


GRANT INSERT ON AUDITORIA TO TRIGGER TR_USUARIOS_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_USUARIOS_CLAVES_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_CLIENTES_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_CLIENTE_CONTACTOS_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_CONSHIST_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_SOLICITUDES_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_COTIZACIONES_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_MATERIALES_PRECIOS_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_MANO_OBRA_PRECIOS_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_MAQUINAS_PRECIOS_AUD;
GRANT INSERT ON AUDITORIA TO TRIGGER TR_EMPRESA_AUD;

/* Lanzar una excepcion con nombre tambien pide privilegio en Firebird 4, y por la
   misma razon: el disparador corre con los privilegios de quien lo invoca. Sin
   esto la escritura sin contexto se rechaza igual -la garantia no corre peligro-
   pero el mensaje habla de permisos en vez de decir que falto el usuario, que es
   lo unico que le sirve a quien lo esta diagnosticando. */
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_USUARIOS_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_USUARIOS_CLAVES_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_CLIENTES_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_CLIENTE_CONTACTOS_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_CONSHIST_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_SOLICITUDES_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_COTIZACIONES_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_MATERIALES_PRECIOS_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_MANO_OBRA_PRECIOS_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_MAQUINAS_PRECIOS_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_EMPRESA_AUD;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

   1. Con la aplicacion, crear un cliente. Tiene que quedar la fila:

      SELECT ID, USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, FECHA
        FROM AUDITORIA ORDER BY ID DESC ROWS 5;

   2. Conectado como ANOVO_BACKEND, intentar escribir a mano. Tiene que seguir
      fallando, y este es el caso que sostiene el diseno:

      INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID)
      VALUES (3, 'insertar', 'CLIENTES', 1);
      -- esperado: no permission for INSERT access to TABLE AUDITORIA

   3. Conectado como ANOVO_BACKEND, escribir sin fijar el contexto. Tiene que dar la
      excepcion propia, no un mensaje de permisos:

      INSERT INTO CLIENTES (NOMBRE) VALUES ('Prueba sin contexto');
      -- esperado: E_AUDITORIA_SIN_USUARIO
      --           "No hay USUARIO_ID en el contexto de sesion..."

   Si la 1 pasa y la 2 falla, el permiso quedo donde tenia que quedar: en el
   disparador, no en el usuario. La 3 confirma que el mensaje apunta a la causa real.

   Aplicado y comprobado el 15/09/2026 sobre AnovoCodigoFuente\Db\ANOVO.FDB. Ver
   Entregables\pruebas\CP-02-auditoria-por-disparadores.md.
---------------------------------------------------------------------------- */

/* ############################################################################
   TRAMO 06_campos_capturados_en_movil.sql
   ############################################################################ */

/* ============================================================================
   06_campos_capturados_en_movil.sql
   Firebird 4.0 - base ANOVO
   16 de septiembre de 2026

   Dos datos que la app movil captura y guarda en SQLite y que Firebird no tenia
   donde recibir. Sin estas columnas se perderian en silencio al sincronizar: el
   telefono los manda, el servidor no tiene donde ponerlos, y nadie se entera.

   Se deja fuera CONTACTO de clientes, que si existe en SQLite: ningun codigo del
   movil la escribe, y repite lo que ya guarda CLIENTE_CONTACTOS.

   Se aplica sobre AnovoCodigoFuente\Db\ANOVO.FDB, la que declara
   Backend\bin\FDConnectionDefs.ini.
   ============================================================================ */

ALTER TABLE CLIENTES
  ADD TIPO_IDENTIFICACION SMALLINT;

/* Los mismos tres valores que el CHECK de SQLite y que el combo del movil. NULL
   es valido: el movil lo guarda asi cuando no se eligio tipo. */
ALTER TABLE CLIENTES
  ADD CONSTRAINT CK_CLIENTES_TIPO_IDENT
  CHECK (TIPO_IDENTIFICACION IS NULL OR TIPO_IDENTIFICACION IN (1, 2, 3));

COMMENT ON COLUMN CLIENTES.TIPO_IDENTIFICACION IS
  '1 cedula fisica, 2 cedula juridica, 3 DIMEX. Mismo valor que en SQLite.';

ALTER TABLE CLIENTE_CONTACTOS
  ADD CELULAR VARCHAR(30);

COMMENT ON COLUMN CLIENTE_CONTACTOS.CELULAR IS
  'Aparte de TELEFONO: en campo el asesor anota los dos.';

COMMIT;

/* ############################################################################
   TRAMO 07_contacto_en_clientes.sql
   ############################################################################ */

/* ============================================================================
   07_contacto_en_clientes.sql
   Firebird 4.0 - base ANOVO
   16 de septiembre de 2026

   Nombre de la persona de contacto que el asesor escribe en la hoja de datos del
   cliente. El 06 lo dejo fuera por error: se concluyo que no se usaba porque el
   guardado local del movil no lo inserta, cuando en realidad la pantalla lo
   captura y es el guardado el que lo pierde.

   Se aplica sobre AnovoCodigoFuente\Db\ANOVO.FDB.
   ============================================================================ */

ALTER TABLE CLIENTES
  ADD CONTACTO D_NOMBRE;

COMMENT ON COLUMN CLIENTES.CONTACTO IS
  'Persona de contacto escrita en la hoja de datos del cliente.';

COMMIT;

/* ############################################################################
   TRAMO 08_permisos.sql
   ############################################################################ */

/* ============================================================================
   08_permisos.sql
   Firebird 4.0 - base ANOVO
   18 de septiembre de 2026

   Permisos por rol en la base, en vez de fijos en los atributos del backend y
   en el menu de cada cliente. La matriz de la minuta 06/2026 (P18 y P19) pasa a
   ser los datos iniciales de ROLES_PERMISOS.

   El AMBITO separa lo de TI de lo de negocio. Las dos FK compuestas de
   ROLES_PERMISOS impiden darle al admin un permiso de negocio y al reves, aunque
   el backend se equivoque.

   Los datos iniciales van antes del disparador de auditoria: el script no tiene
   USUARIO_ID en el contexto y el disparador los rechazaria.

   Se aplica sobre AnovoCodigoFuente\Db\ANOVO.FDB.
   ============================================================================ */

CREATE DOMAIN D_AMBITO AS VARCHAR(15)
  CHECK (VALUE IN ('negocio', 'administracion'));

/* ---- ROLES --------------------------------------------------------------- */

ALTER TABLE ROLES
  ADD AMBITO D_AMBITO DEFAULT 'negocio' NOT NULL;

COMMIT;

UPDATE ROLES SET AMBITO = 'administracion' WHERE CODIGO = 'admin';

COMMIT;

/* Redundante con la PK, pero la FK compuesta de ROLES_PERMISOS necesita un
   UNIQUE exacto sobre (ID, AMBITO) al que apuntar. */
ALTER TABLE ROLES
  ADD CONSTRAINT UQ_ROLES_ID_AMBITO UNIQUE (ID, AMBITO);

COMMENT ON COLUMN ROLES.AMBITO IS
  'negocio o administracion. Decide que permisos puede recibir el rol.';

/* ---- PERMISOS -------------------------------------------------------------
   Catalogo fijo: lo carga este script, la aplicacion solo lo lee. Un permiso
   nuevo viene con codigo nuevo en el backend, no se inventa desde la pantalla. */

CREATE TABLE PERMISOS (
  ID     INTEGER PRIMARY KEY,
  CODIGO VARCHAR(50) NOT NULL UNIQUE,
  NOMBRE D_NOMBRE    NOT NULL,
  MODULO VARCHAR(30) NOT NULL,
  AMBITO D_AMBITO    NOT NULL,
  CONSTRAINT UQ_PERMISOS_ID_AMBITO UNIQUE (ID, AMBITO)
);

COMMENT ON TABLE PERMISOS IS
  'Operaciones que el backend autoriza. El codigo es el que declara cada accion.';

/* ---- ROLES_PERMISOS -------------------------------------------------------
   Un permiso se otorga o se quita: insert o delete, sin update. Aqui el borrado
   fisico si vale, el rastro queda en AUDITORIA. */

CREATE TABLE ROLES_PERMISOS (
  ROL_ID         INTEGER   NOT NULL,
  PERMISO_ID     INTEGER   NOT NULL,
  AMBITO         D_AMBITO  NOT NULL,
  FECHA_CREACION D_TIMESTAMP,
  CONSTRAINT PK_ROLES_PERMISOS PRIMARY KEY (ROL_ID, PERMISO_ID),
  CONSTRAINT FK_ROLPERM_ROL     FOREIGN KEY (ROL_ID, AMBITO)
    REFERENCES ROLES (ID, AMBITO),
  CONSTRAINT FK_ROLPERM_PERMISO FOREIGN KEY (PERMISO_ID, AMBITO)
    REFERENCES PERMISOS (ID, AMBITO)
);

CREATE INDEX IDX_ROLPERM_PERMISO ON ROLES_PERMISOS (PERMISO_ID);

COMMENT ON COLUMN ROLES_PERMISOS.AMBITO IS
  'Copia del ambito del permiso. Si no coincide con el del rol, falla la FK.';

COMMIT;

