/* ============================================================================
   AUDITORIA
   ============================================================================ */

SET TERM ^ ;

CREATE TRIGGER TR_ROLES_PERMISOS_AUD FOR ROLES_PERMISOS
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_ACCION  VARCHAR(50);
  DECLARE VARIABLE V_ROL     INTEGER;
  DECLARE VARIABLE V_PERMISO INTEGER;
BEGIN
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  IF (INSERTING) THEN BEGIN V_ACCION = 'insertar';   V_ROL = NEW.ROL_ID; V_PERMISO = NEW.PERMISO_ID; END
  ELSE IF (UPDATING) THEN BEGIN V_ACCION = 'actualizar'; V_ROL = NEW.ROL_ID; V_PERMISO = NEW.PERMISO_ID; END
  ELSE BEGIN V_ACCION = 'borrar'; V_ROL = OLD.ROL_ID; V_PERMISO = OLD.PERMISO_ID; END
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'ROLES_PERMISOS', :V_ROL, 'permiso ' || :V_PERMISO);
END^

SET TERM ; ^

/* ============================================================================
   PERMISOS DE BASE DE DATOS
   ============================================================================ */

GRANT SELECT                 ON PERMISOS       TO ROL_BACKEND;
GRANT SELECT, INSERT, DELETE ON ROLES_PERMISOS TO ROL_BACKEND;

GRANT INSERT ON AUDITORIA TO TRIGGER TR_ROLES_PERMISOS_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_ROLES_PERMISOS_AUD;

COMMIT;

/* ############################################################################
   TRAMO 09_usuarios_prueba.sql
   ############################################################################ */

/* ============================================================================
   09_usuarios_prueba.sql
   Firebird 4.0 - base ANOVO
   18 de septiembre de 2026

   Tres usuarios de prueba para los casos que los cinco del 02 no cubren:

     asesor2      segundo asesor: un asesor no ve lo del otro
     provisional  clave provisional: token clave_vencida, sin permisos
     inactivo     cuenta inactiva: el login lo rechaza igual que una clave mala

   Datos de prueba, no van en produccion.

   La clave se copia del hash de asesor@anovo.test en vez de escribirlo aqui:
   la carpeta esta en git. En una base reconstruida desde cero ese hash todavia
   es el marcador del 02, y estos tres tampoco entran hasta regenerarlo.

   USUARIOS y USUARIOS_CLAVES estan auditadas: el script se identifica como el
   admin de prueba para que los disparadores no lo rechacen.
   ============================================================================ */


COMMIT;

/* ############################################################################
   TRAMO 10_auditoria_detalle.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 10: el detalle de la auditoria lo pone el servicio
   ----------------------------------------------------------------------------
   AUDITORIA.DETALLE quedaba nulo en casi todo: el disparador sabe que cambio
   una fila, pero no por que. Quien si lo sabe es el servicio, que conoce la
   intencion -una edicion de datos, una revocacion de consentimiento-.

   El servicio deja el texto en el contexto de sesion antes de escribir y el
   disparador lo recoge:

     RDB$SET_CONTEXT('USER_SESSION', 'DETALLE', 'Revocacion del consentimiento')

   La fila no se inserta desde la aplicacion a proposito: el disparador la pone
   igual y serian dos. Asi tampoco se pierde la auditoria si alguien escribe
   por otra via; lo unico que faltaria es el texto.

   Los disparadores que ya traian un detalle fijo -cambio de clave, la nota de
   la Ley 8968, precio, permiso- lo conservan como respaldo con COALESCE.

   El contexto vive mientras dure la conexion, y la conexion se reutiliza entre
   peticiones: el middleware lo limpia al terminar, junto con el usuario.
   ============================================================================ */

SET TERM ^ ;

CREATE OR ALTER TRIGGER TR_USUARIOS_AUD FOR USUARIOS
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_ACCION  VARCHAR(50);
  DECLARE VARIABLE V_ID      INTEGER;
  DECLARE VARIABLE V_DETALLE VARCHAR(500);
BEGIN
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  /* Lo deja el servicio antes de escribir; si no lo deja, queda nulo. */
  V_DETALLE = RDB$GET_CONTEXT('USER_SESSION', 'DETALLE');
  IF (INSERTING) THEN BEGIN V_ACCION = 'insertar';   V_ID = NEW.ID; END
  ELSE IF (UPDATING) THEN BEGIN V_ACCION = 'actualizar'; V_ID = NEW.ID; END
  ELSE BEGIN V_ACCION = 'borrar'; V_ID = OLD.ID; END
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'USUARIOS', :V_ID, :V_DETALLE);
END^

CREATE OR ALTER TRIGGER TR_USUARIOS_CLAVES_AUD FOR USUARIOS_CLAVES
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_ACCION  VARCHAR(50);
  DECLARE VARIABLE V_ID      INTEGER;
  DECLARE VARIABLE V_DETALLE VARCHAR(500);
BEGIN
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  /* Lo deja el servicio antes de escribir; si no lo deja, queda nulo. */
  V_DETALLE = RDB$GET_CONTEXT('USER_SESSION', 'DETALLE');
  IF (INSERTING) THEN BEGIN V_ACCION = 'insertar';   V_ID = NEW.USUARIO_ID; END
  ELSE IF (UPDATING) THEN BEGIN V_ACCION = 'actualizar'; V_ID = NEW.USUARIO_ID; END
  ELSE BEGIN V_ACCION = 'borrar'; V_ID = OLD.USUARIO_ID; END
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'USUARIOS_CLAVES', :V_ID,
          COALESCE(:V_DETALLE, 'cambio de clave'));
END^

