/* ############################################################################
   TRAMO 11_categorias_mano_obra.sql
   ############################################################################ */

/* ============================================================================
   Las categorias de mano de obra dejan de ser un catalogo cerrado.
   ----------------------------------------------------------------------------
   Lo estructural -IDENTITY y ACTIVO- ya esta en el tramo 01: desde cero la
   tabla se crea abierta y no hacen falta el generador ni el disparador
   BEFORE INSERT que si lleva la migracion 11 sobre una base ya creada.

   Aqui quedan las dos cosas que si son iguales en los dos caminos: la
   auditoria y el permiso de escritura del backend.
   ============================================================================ */

SET TERM ^ ;

CREATE TRIGGER TR_MANO_OBRA_CATEGORIA_AUD FOR MANO_OBRA_CATEGORIA
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_ACCION  VARCHAR(50);
  DECLARE VARIABLE V_ID      INTEGER;
  DECLARE VARIABLE V_DETALLE VARCHAR(500);
BEGIN
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  V_DETALLE = RDB$GET_CONTEXT('USER_SESSION', 'DETALLE');
  IF (INSERTING) THEN BEGIN V_ACCION = 'insertar';   V_ID = NEW.ID; END
  ELSE IF (UPDATING) THEN BEGIN V_ACCION = 'actualizar'; V_ID = NEW.ID; END
  ELSE BEGIN V_ACCION = 'borrar'; V_ID = OLD.ID; END
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'MANO_OBRA_CATEGORIA', :V_ID, :V_DETALLE);
END^

SET TERM ; ^

COMMIT;

/* En Firebird 4 los disparadores corren como SQL SECURITY INVOKER, o sea con
   los privilegios de ANOVO_BACKEND, a quien se le retiro todo sobre AUDITORIA. */
GRANT INSERT ON AUDITORIA TO TRIGGER TR_MANO_OBRA_CATEGORIA_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_MANO_OBRA_CATEGORIA_AUD;

/* Sin DELETE: aqui nada se borra, una categoria en desuso se inactiva. */
GRANT INSERT, UPDATE ON MANO_OBRA_CATEGORIA TO ROL_BACKEND;

COMMIT;


/* ############################################################################
   TRAMO 13_usuario_sistema.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 13: usuario Sistema, para lo que escribe el servidor solo
   ----------------------------------------------------------------------------
   Los disparadores de auditoria exigen usuario en contexto y tumban la
   escritura con E_AUDITORIA_SIN_USUARIO si no lo hay. Eso funciona porque toda
   escritura venia de una peticion con token.

   La rutina de vigencia de precios rompe ese supuesto: corre en el servidor,
   al arrancar y cada hora, sin nadie que la haya pedido. Necesita un usuario
   que ponerse, y no puede ser uno real: la auditoria diria que una persona
   cambio el precio cuando no lo hizo.

   Este usuario existe solo para aparecer en AUDITORIA. No puede entrar:

     - ACTIVO = FALSE, que el login rechaza antes de mirar la clave;
     - sin fila en USUARIOS_CLAVES, que el login vuelve a rechazar.

   Son dos barreras independientes. Si alguien lo reactivara por error, sigue
   sin clave con la cual entrar.

   El rol es el de administrador porque la columna es obligatoria y hay que
   poner alguno. No le concede nada: los permisos se revisan por peticion y
   este usuario no tiene peticiones.

   No lleva ID fijo. El servidor lo busca por correo al arrancar, asi que la
   identidad puede asignarlo como a cualquier otro.

   USUARIOS esta auditada, asi que el script se identifica como el primer
   administrador activo de la base, que es quien la esta migrando.
   ============================================================================ */

SELECT RDB$SET_CONTEXT('USER_SESSION', 'USUARIO_ID',
  (SELECT ID FROM USUARIOS WHERE CORREO = 'sistema@anovo.local'))
  FROM RDB$DATABASE;

INSERT INTO USUARIOS (CORREO, NOMBRE, ROL_ID, ACTIVO, DEBE_CAMBIAR_CLAVE)
  SELECT 'sistema@anovo.local', 'Sistema', 5, FALSE, FALSE
    FROM RDB$DATABASE
   WHERE NOT EXISTS (SELECT 1 FROM USUARIOS
                      WHERE CORREO = 'sistema@anovo.local');

SELECT RDB$SET_CONTEXT('USER_SESSION', 'USUARIO_ID', NULL) FROM RDB$DATABASE;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

     SELECT U.ID, U.CORREO, U.ACTIVO,
            (SELECT COUNT(*) FROM USUARIOS_CLAVES C WHERE C.USUARIO_ID = U.ID)
       FROM USUARIOS U
      WHERE U.CORREO = 'sistema@anovo.local';

   Tiene que salir ACTIVO en <false> y la cuenta de claves en 0.
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 14_precios_programados.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 14: cola de cambios de precio programados
   ----------------------------------------------------------------------------
   Un cambio con fecha futura no es un precio: es la intencion de cambiarlo.
   Guardarlo en MATERIALES_PRECIOS como fila inactiva mezclaba dos cosas en la
   misma tabla y obligaba a distinguir lo historico de lo pendiente comparando
   fechas, que es de donde salia el fallo del antefechado.

   Aqui viven aparte. Las tablas de precios vuelven a guardar solo precios que
   rigieron o rigen, y la auditoria queda con dos hechos distintos: la persona
   programo el cambio, y Sistema lo aplico cuando llego la fecha.

   Una sola tabla para los tres catalogos y no tres tablas: el cambio tiene la
   misma forma en los tres, el servidor lee una sola cola, y el escritorio ya
   los trata como uno solo en mtPrecioCatalogo. La integridad no se pierde
   porque cada catalogo lleva su propia llave foranea y un CHECK obliga a que
   venga exactamente una.

   Al aplicarse queda PRECIO_ID con la fila que se creo en la tabla de precios
   que corresponda. Esa es la traza que une la intencion con el hecho.
   ============================================================================ */

CREATE TABLE PRECIOS_PROGRAMADOS (
  ID               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

  /* Exactamente una, segun el catalogo. */
  MATERIAL_ID      INTEGER REFERENCES MATERIALES(ID),
  MANO_OBRA_ID     INTEGER REFERENCES MANO_OBRA(ID),
  MAQUINA_ID       INTEGER REFERENCES MAQUINAS(ID),

  /* Tambien segun el catalogo: materiales llevan costo y precio de venta,
     mano de obra solo costo, maquinas costo por hora. */
  COSTO_UNITARIO   NUMERIC(15,2),
  PRECIO_UNITARIO  NUMERIC(15,2),
  COSTO_HORA       NUMERIC(15,2),

  /* Sin el DEFAULT de D_TIMESTAMP a proposito: por omision seria ahora, que
     significa "de una vez", justo lo contrario de programar. */
  FECHA_VIGENCIA   TIMESTAMP NOT NULL,

  ESTADO           D_ESTADO DEFAULT 'pendiente' NOT NULL,
  PRECIO_ID        INTEGER,
  FECHA_APLICACION TIMESTAMP,

  CREADO_POR       INTEGER REFERENCES USUARIOS(ID),
  FECHA_CREACION   D_TIMESTAMP,

  CONSTRAINT CK_PRECIOPROG_ITEM CHECK (
    (CASE WHEN MATERIAL_ID  IS NULL THEN 0 ELSE 1 END +
     CASE WHEN MANO_OBRA_ID IS NULL THEN 0 ELSE 1 END +
     CASE WHEN MAQUINA_ID   IS NULL THEN 0 ELSE 1 END) = 1),
  CONSTRAINT CK_PRECIOPROG_ESTADO CHECK (
    ESTADO IN ('pendiente','aplicado','cancelado')),
  CONSTRAINT CK_PRECIOPROG_APLICADO CHECK (
    ESTADO <> 'aplicado' OR PRECIO_ID IS NOT NULL)
);

/* Es la consulta que el servidor corre cada hora: lo pendiente que ya vencio. */
CREATE INDEX IDX_PRECIOPROG_PENDIENTE
  ON PRECIOS_PROGRAMADOS (ESTADO, FECHA_VIGENCIA);

/* Para listar lo pendiente de un item en la ventana del catalogo. */
CREATE INDEX IDX_PRECIOPROG_MATERIAL  ON PRECIOS_PROGRAMADOS (MATERIAL_ID);
CREATE INDEX IDX_PRECIOPROG_MANO_OBRA ON PRECIOS_PROGRAMADOS (MANO_OBRA_ID);
CREATE INDEX IDX_PRECIOPROG_MAQUINA   ON PRECIOS_PROGRAMADOS (MAQUINA_ID);

COMMIT;

SET TERM ^ ;

CREATE TRIGGER TR_PRECIOS_PROGRAMADOS_AUD FOR PRECIOS_PROGRAMADOS
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_ACCION  VARCHAR(50);
  DECLARE VARIABLE V_ID      INTEGER;
  DECLARE VARIABLE V_DETALLE VARCHAR(500);
BEGIN
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  V_DETALLE = RDB$GET_CONTEXT('USER_SESSION', 'DETALLE');
  IF (INSERTING) THEN BEGIN V_ACCION = 'insertar';   V_ID = NEW.ID; END
  ELSE IF (UPDATING) THEN BEGIN V_ACCION = 'actualizar'; V_ID = NEW.ID; END
  ELSE BEGIN V_ACCION = 'borrar'; V_ID = OLD.ID; END
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'PRECIOS_PROGRAMADOS', :V_ID,
          COALESCE(:V_DETALLE, 'cambio de precio programado'));
END^

SET TERM ; ^

COMMIT;

/* ----------------------------------------------------------------------------
   PERMISOS

   ROL_BACKEND solo puede lo que necesita. No lleva DELETE: un cambio que ya no
   va se cancela, no se borra, o se perderia el rastro de que alguien lo
   programo. El disparador necesita los suyos aparte porque corre con SQL
   SECURITY INVOKER y al rol se le retiro todo sobre AUDITORIA.
   ---------------------------------------------------------------------------- */

GRANT SELECT, INSERT, UPDATE ON PRECIOS_PROGRAMADOS TO ROL_BACKEND;

GRANT INSERT ON AUDITORIA TO TRIGGER TR_PRECIOS_PROGRAMADOS_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO
  TO TRIGGER TR_PRECIOS_PROGRAMADOS_AUD;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

     SELECT RDB$CONSTRAINT_NAME FROM RDB$RELATION_CONSTRAINTS
      WHERE RDB$RELATION_NAME = 'PRECIOS_PROGRAMADOS';

   Tienen que salir los tres CK_PRECIOPROG_*, la llave primaria y las tres
   foraneas.
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 15_unidades_medida.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 15: unidades de medida administrables
   ----------------------------------------------------------------------------
   Las unidades de materiales y mano de obra eran texto libre, escogido de una
   lista fija en el escritorio. El patrocinador pidio poder administrarlas
   (minuta 09/2026): pasan a un catalogo propio, clasificado por magnitud, y
   MATERIALES y MANO_OBRA lo referencian por clave foranea.

   COTIZACION_DETALLE no cambia: guarda el nombre de la unidad como texto
   porque es la foto de lo que se cotizo. SOLICITUD_MEDIDAS tampoco: sus
   unidades (cm, mm, grados) son las del croquis, otro asunto.

   Todo en ASCII, como el resto de los scripts: 'lamina' sin tilde y 'm2' en
   vez del superindice. Una tilde en el script depende del juego de caracteres
   de la conexion con que se aplique, y puede quedar danada en la base.
   ============================================================================ */

/* ----------------------------------------------------------------------------
   1. La tabla. NOMBRE tiene 20 porque COTIZACION_DETALLE.UNIDAD_MEDIDA es
   VARCHAR(20) y copia el nombre al armar la cotizacion. La magnitud es una
   palabra fija, como los estados de la cotizacion; el texto que ve el usuario
   sale de Anovo.Textos. Sin UUID_LOCAL: los catalogos no bajan al movil.
   ---------------------------------------------------------------------------- */
CREATE TABLE UNIDADES_MEDIDA (
  ID                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  NOMBRE             VARCHAR(20) NOT NULL,
  ABREVIATURA        VARCHAR(10),
  MAGNITUD           VARCHAR(10) NOT NULL,
  ACTIVO             D_BOOLEANO,
  FECHA_CREACION     D_TIMESTAMP,
  FECHA_MODIFICACION D_TIMESTAMP,
  CONSTRAINT CK_UNIDADES_MEDIDA_MAGNITUD
    CHECK (MAGNITUD IN ('tiempo', 'peso', 'longitud', 'area', 'volumen', 'unidades'))
);

/* Unico sin distinguir mayusculas: no puede haber 'Metro' y 'metro'. */
CREATE UNIQUE INDEX UQ_UNIDADES_MEDIDA_NOMBRE
  ON UNIDADES_MEDIDA COMPUTED BY (UPPER(NOMBRE));

COMMIT;

/* ----------------------------------------------------------------------------
   2. La siembra. Va antes del disparador de auditoria: es la carga inicial, no
   una operacion de usuario, y asi no depende de que exista un administrador.
   Las abreviaturas son una propuesta; se corrigen desde la pestana.
   ---------------------------------------------------------------------------- */
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('hora',           'h',    'tiempo');
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('kilogramo',      'kg',   'peso');
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('tonelada',       't',    'peso');
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('metro',          'm',    'longitud');
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('pulgada',        'pulg', 'longitud');
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('metro cuadrado', 'm2',   'area');
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('litro',          'L',    'volumen');
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('unidad',         'und',  'unidades');
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('lamina',         'lam',  'unidades');
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD) VALUES ('tubo',           'tubo', 'unidades');

COMMIT;

/* ----------------------------------------------------------------------------
   3. Textos en uso con otra forma. 'kilo' viene de la carga de prueba. Estas
   tablas no se auditan (03_auditoria.sql: lo sensible es el precio), asi que
   no hace falta usuario en la sesion.
   ---------------------------------------------------------------------------- */
UPDATE MATERIALES SET UNIDAD_MEDIDA = 'kilogramo' WHERE UNIDAD_MEDIDA = 'kilo';
UPDATE MANO_OBRA  SET UNIDAD_MEDIDA = 'kilogramo' WHERE UNIDAD_MEDIDA = 'kilo';

/* Cualquier otro texto que no este en la siembra entra al catalogo tal cual,
   como 'unidades', para no perder el dato. Queda para revisarlo desde la
   pestana de unidades. */
INSERT INTO UNIDADES_MEDIDA (NOMBRE, MAGNITUD)
  SELECT DISTINCT TRIM(X.U), 'unidades'
    FROM (SELECT UNIDAD_MEDIDA AS U FROM MATERIALES
          UNION SELECT UNIDAD_MEDIDA FROM MANO_OBRA) X
   WHERE NOT EXISTS (SELECT 1 FROM UNIDADES_MEDIDA M
                      WHERE UPPER(M.NOMBRE) = UPPER(TRIM(X.U)));

COMMIT;

/* ----------------------------------------------------------------------------
   4. De texto a clave foranea: MATERIALES. El COMMIT despues del ADD es
   necesario: Firebird no deja usar en la misma transaccion una columna recien
   agregada por DDL.
   ---------------------------------------------------------------------------- */
ALTER TABLE MATERIALES ADD UNIDAD_MEDIDA_ID INTEGER;
COMMIT;

UPDATE MATERIALES T SET UNIDAD_MEDIDA_ID =
  (SELECT M.ID FROM UNIDADES_MEDIDA M
    WHERE UPPER(M.NOMBRE) = UPPER(TRIM(T.UNIDAD_MEDIDA)));
COMMIT;

ALTER TABLE MATERIALES ALTER UNIDAD_MEDIDA_ID SET NOT NULL;
ALTER TABLE MATERIALES ADD CONSTRAINT FK_MATERIALES_UNIDAD
  FOREIGN KEY (UNIDAD_MEDIDA_ID) REFERENCES UNIDADES_MEDIDA (ID);
CREATE INDEX IDX_MATERIALES_UNIDAD ON MATERIALES (UNIDAD_MEDIDA_ID);
ALTER TABLE MATERIALES DROP UNIDAD_MEDIDA;
COMMIT;

/* ----------------------------------------------------------------------------
   5. Lo mismo para MANO_OBRA.
   ---------------------------------------------------------------------------- */
ALTER TABLE MANO_OBRA ADD UNIDAD_MEDIDA_ID INTEGER;
COMMIT;

UPDATE MANO_OBRA T SET UNIDAD_MEDIDA_ID =
  (SELECT M.ID FROM UNIDADES_MEDIDA M
    WHERE UPPER(M.NOMBRE) = UPPER(TRIM(T.UNIDAD_MEDIDA)));
COMMIT;

ALTER TABLE MANO_OBRA ALTER UNIDAD_MEDIDA_ID SET NOT NULL;
ALTER TABLE MANO_OBRA ADD CONSTRAINT FK_MANO_OBRA_UNIDAD
  FOREIGN KEY (UNIDAD_MEDIDA_ID) REFERENCES UNIDADES_MEDIDA (ID);
CREATE INDEX IDX_MANO_OBRA_UNIDAD ON MANO_OBRA (UNIDAD_MEDIDA_ID);
ALTER TABLE MANO_OBRA DROP UNIDAD_MEDIDA;
COMMIT;

SET TERM ^ ;

/* ----------------------------------------------------------------------------
   6. Fecha de modificacion, como en los demas catalogos.
   ---------------------------------------------------------------------------- */
CREATE TRIGGER TR_UNIDADES_MEDIDA_BU FOR UNIDADES_MEDIDA
ACTIVE BEFORE UPDATE POSITION 0
AS
BEGIN
  NEW.FECHA_MODIFICACION = CURRENT_TIMESTAMP;
END^

/* ----------------------------------------------------------------------------
   7. Auditoria, igual que MANO_OBRA_CATEGORIA (migracion 11): el catalogo lo
   edita la empresa, asi que queda quien lo cambio. Sin usuario en la sesion la
   escritura falla en vez de registrarse como anonima.
   ---------------------------------------------------------------------------- */
CREATE TRIGGER TR_UNIDADES_MEDIDA_AUD FOR UNIDADES_MEDIDA
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_ACCION  VARCHAR(50);
  DECLARE VARIABLE V_ID      INTEGER;
  DECLARE VARIABLE V_DETALLE VARCHAR(500);
BEGIN
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  V_DETALLE = RDB$GET_CONTEXT('USER_SESSION', 'DETALLE');
  IF (INSERTING) THEN BEGIN V_ACCION = 'insertar';   V_ID = NEW.ID; END
  ELSE IF (UPDATING) THEN BEGIN V_ACCION = 'actualizar'; V_ID = NEW.ID; END
  ELSE BEGIN V_ACCION = 'borrar'; V_ID = OLD.ID; END
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'UNIDADES_MEDIDA', :V_ID, :V_DETALLE);
END^

SET TERM ; ^

COMMIT;

/* ----------------------------------------------------------------------------
   8. Permisos. El disparador corre como el invocador (Firebird 4), que es
   ANOVO_BACKEND, sin acceso directo a AUDITORIA. Sin DELETE para el backend:
   una unidad que ya no se usa se inactiva.
   ---------------------------------------------------------------------------- */
GRANT INSERT ON AUDITORIA TO TRIGGER TR_UNIDADES_MEDIDA_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_UNIDADES_MEDIDA_AUD;
GRANT SELECT, INSERT, UPDATE ON UNIDADES_MEDIDA TO ROL_BACKEND;

COMMIT;


/* ############################################################################
   TRAMO 16_gerencia_sin_elaborar.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 16: gerencia revisa y aprueba, no elabora
   ----------------------------------------------------------------------------
   Gerencia tenia cotizaciones.elaborar desde la matriz inicial. Con la cola
   comun de solicitudes eso le permitia tomar solicitudes y crear cotizaciones,
   y Marcos definio el 27/09/2026 que gerencia solo revisa y aprueba: tomar de
   la cola es del asistente y del supervisor.

   Se quita el permiso en la base, no solo en el menu: el servidor evalua los
   permisos en cada peticion contra ROLES_PERMISOS, y un boton oculto no
   impide llamar a la API.

   ROLES_PERMISOS esta auditada: el script se identifica como el primer
   administrador activo, que es quien migra, como en la migracion 13.

   Despues de aplicarla, invalidar la cache de permisos desde la ventana del
   servidor o reiniciarlo.
   ============================================================================ */

SELECT RDB$SET_CONTEXT('USER_SESSION', 'USUARIO_ID',
  (SELECT ID FROM USUARIOS WHERE CORREO = 'sistema@anovo.local'))
  FROM RDB$DATABASE;
SELECT RDB$SET_CONTEXT('USER_SESSION', 'DETALLE',
  'Gerencia revisa y aprueba cotizaciones; no las elabora')
  FROM RDB$DATABASE;

DELETE FROM ROLES_PERMISOS
 WHERE ROL_ID = (SELECT ID FROM ROLES WHERE CODIGO = 'gerencia')
   AND PERMISO_ID = (SELECT ID FROM PERMISOS
                      WHERE CODIGO = 'cotizaciones.elaborar');

SELECT RDB$SET_CONTEXT('USER_SESSION', 'DETALLE', NULL) FROM RDB$DATABASE;
SELECT RDB$SET_CONTEXT('USER_SESSION', 'USUARIO_ID', NULL) FROM RDB$DATABASE;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

     SELECT R.CODIGO, P.CODIGO
       FROM ROLES_PERMISOS RP
       JOIN ROLES R ON R.ID = RP.ROL_ID
       JOIN PERMISOS P ON P.ID = RP.PERMISO_ID
      WHERE P.CODIGO = 'cotizaciones.elaborar';

   Tienen que salir solo asistente y supervisor.
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 17_gerencia_elabora.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 17: gerencia vuelve a elaborar cotizaciones
   ----------------------------------------------------------------------------
   Revierte la 16. La minuta 07/2026 (tema 2), firmada por el patrocinador,
   dice que gerencia elabora y modifica cotizaciones; la 16 se lo habia
   quitado sin un acuerdo nuevo que la respalde. Mientras no haya una minuta
   que cambie esa matriz, manda la firmada.

   La 16 no se edita ni se borra porque ya se aplico: los scripts son
   acumulativos y un cambio es un script nuevo.

   Despues de aplicarla, invalidar la cache de permisos desde la ventana del
   servidor o reiniciarlo.
   ============================================================================ */

SELECT RDB$SET_CONTEXT('USER_SESSION', 'USUARIO_ID',
  (SELECT ID FROM USUARIOS WHERE CORREO = 'sistema@anovo.local'))
  FROM RDB$DATABASE;
SELECT RDB$SET_CONTEXT('USER_SESSION', 'DETALLE',
  'Gerencia elabora cotizaciones segun la minuta 07/2026')
  FROM RDB$DATABASE;

INSERT INTO ROLES_PERMISOS (ROL_ID, PERMISO_ID, AMBITO)
  SELECT R.ID, P.ID, 'negocio'
    FROM ROLES R, PERMISOS P
   WHERE R.CODIGO = 'gerencia'
     AND P.CODIGO = 'cotizaciones.elaborar'
     AND NOT EXISTS (SELECT 1 FROM ROLES_PERMISOS RP
                      WHERE RP.ROL_ID = R.ID AND RP.PERMISO_ID = P.ID);

SELECT RDB$SET_CONTEXT('USER_SESSION', 'DETALLE', NULL) FROM RDB$DATABASE;
SELECT RDB$SET_CONTEXT('USER_SESSION', 'USUARIO_ID', NULL) FROM RDB$DATABASE;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

     SELECT R.CODIGO FROM ROLES_PERMISOS RP
       JOIN ROLES R ON R.ID = RP.ROL_ID
       JOIN PERMISOS P ON P.ID = RP.PERMISO_ID
      WHERE P.CODIGO = 'cotizaciones.elaborar';

   Tienen que salir asistente, supervisor y gerencia.
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 18_vistas_lectura.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 18: vistas de lectura
   ----------------------------------------------------------------------------
   Las consultas de lectura repetian los mismos joins en varios archivos
   Anovo.SQL.*: solicitud con cliente y asesor, cotizacion con cliente,
   asesor y quien la elaboro, y los tres catalogos con su precio vigente.
   Pasan a vistas: se escriben una vez, el generador de entidades las lee
   como cualquier tabla (sin llave primaria, de solo lectura) y los reportes
   se arman sobre ellas.

   Las vistas describen los datos, no deciden nada: sin parametros y sin
   reglas de negocio. Quien consulta, que estados cuentan como en curso y la
   paginacion siguen en el repositorio, como filtros sobre la vista.

   Todo en ASCII, como el resto de los scripts.
   ============================================================================ */

/* ----------------------------------------------------------------------------
   1. V_SOLICITUDES. FECHA_RECEPCION cae a la de captura mientras la solicitud
   no se ha recibido, y DIAS_ESPERA se cuenta desde ahi.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_SOLICITUDES AS
SELECT S.ID, S.ESTADO, S.DESCRIPCION, S.FECHA_CAPTURA,
       COALESCE(S.FECHA_RECEPCION, S.FECHA_CAPTURA) AS FECHA_RECEPCION,
       S.CLIENTE_ID, C.NOMBRE AS CLIENTE_NOMBRE,
       S.ASESOR_ID, A.NOMBRE AS ASESOR_NOMBRE,
       CAST(DATEDIFF(DAY FROM COALESCE(S.FECHA_RECEPCION, S.FECHA_CAPTURA)
                     TO CURRENT_TIMESTAMP) AS INTEGER) AS DIAS_ESPERA,
       CASE WHEN EXISTS (SELECT 1 FROM COTIZACIONES X
                          WHERE X.SOLICITUD_ID = S.ID)
            THEN TRUE ELSE FALSE END AS TIENE_COTIZACION
  FROM SOLICITUDES S
  JOIN CLIENTES C ON C.ID = S.CLIENTE_ID
  JOIN USUARIOS A ON A.ID = S.ASESOR_ID;

/* ----------------------------------------------------------------------------
   2. V_COTIZACIONES. DEVUELTA: borrador con observacion del supervisor.
   DIAS_EN_ESTADO se mide con FECHA_MODIFICACION, porque no hay fecha propia
   de presentacion ni de rechazo. DIAS_RESPUESTA va de la recepcion de la
   solicitud a la aprobacion; nulo si no se aprobo.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_COTIZACIONES AS
SELECT K.ID, K.NUMERO, K.ESTADO, K.DESCRIPCION_TRABAJO,
       K.SUBTOTAL_MATERIALES, K.SUBTOTAL_MANO_OBRA, K.SUBTOTAL_MAQUINA,
       K.COSTO_TOTAL, K.PORCENTAJE_AJUSTE, K.MOTIVO_AJUSTE, K.PORCENTAJE_IVA,
       K.MONTO_IMPUESTO, K.MONTO_TOTAL, K.MOTIVO_RECHAZO,
       K.FECHA_ELABORACION, K.FECHA_APROBACION, K.FECHA_ENVIO,
       K.FECHA_MODIFICACION,
       K.SOLICITUD_ID,
       COALESCE(S.FECHA_RECEPCION, S.FECHA_CAPTURA) AS FECHA_RECEPCION,
       K.CLIENTE_ID, C.NOMBRE AS CLIENTE_NOMBRE,
       S.ASESOR_ID, A.NOMBRE AS ASESOR_NOMBRE,
       K.ELABORADA_POR, E.NOMBRE AS ELABORADA_POR_NOMBRE,
       K.APROBADA_POR, P.NOMBRE AS APROBADA_POR_NOMBRE,
       K.TIPO_TRABAJO_ID, T.NOMBRE AS TIPO_TRABAJO_NOMBRE,
       CASE WHEN K.ESTADO = 'borrador' AND K.MOTIVO_RECHAZO IS NOT NULL
            THEN TRUE ELSE FALSE END AS DEVUELTA,
       CAST(DATEDIFF(DAY FROM K.FECHA_MODIFICACION TO CURRENT_TIMESTAMP)
            AS INTEGER) AS DIAS_EN_ESTADO,
       CASE WHEN K.FECHA_APROBACION IS NOT NULL
            THEN CAST(DATEDIFF(DAY FROM COALESCE(S.FECHA_RECEPCION,
                      S.FECHA_CAPTURA) TO K.FECHA_APROBACION) AS INTEGER)
       END AS DIAS_RESPUESTA
  FROM COTIZACIONES K
  JOIN SOLICITUDES S ON S.ID = K.SOLICITUD_ID
  JOIN CLIENTES C ON C.ID = K.CLIENTE_ID
  JOIN USUARIOS A ON A.ID = S.ASESOR_ID
  JOIN USUARIOS E ON E.ID = K.ELABORADA_POR
  LEFT JOIN USUARIOS P ON P.ID = K.APROBADA_POR
  LEFT JOIN TIPOS_TRABAJO T ON T.ID = K.TIPO_TRABAJO_ID;

/* ----------------------------------------------------------------------------
   3. V_CATALOGO_ITEMS. Los tres catalogos con su precio vigente y el proximo
   cambio programado. COSTO es el costo comparable entre tipos: el unitario en
   materiales y mano de obra, el de la hora en maquinas, que se miden en hora.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_CATALOGO_ITEMS AS
SELECT CAST('material' AS VARCHAR(10)) AS TIPO,
       M.ID, M.CODIGO, M.NOMBRE, M.DESCRIPCION,
       M.UNIDAD_MEDIDA_ID, U.NOMBRE AS UNIDAD_MEDIDA,
       CAST(NULL AS INTEGER) AS CATEGORIA_ID,
       P.COSTO_UNITARIO, P.PRECIO_UNITARIO,
       CAST(NULL AS NUMERIC(15,2)) AS COSTO_HORA,
       P.COSTO_UNITARIO AS COSTO, P.FECHA_VIGENCIA, M.ACTIVO,
       (SELECT MIN(PP.FECHA_VIGENCIA) FROM PRECIOS_PROGRAMADOS PP
         WHERE PP.MATERIAL_ID = M.ID AND PP.ESTADO = 'pendiente')
         AS PROGRAMADO_FECHA
  FROM MATERIALES M
  JOIN UNIDADES_MEDIDA U ON U.ID = M.UNIDAD_MEDIDA_ID
  LEFT JOIN MATERIALES_PRECIOS P
    ON P.MATERIAL_ID = M.ID AND P.ACTIVO = TRUE
UNION ALL
SELECT CAST('mano_obra' AS VARCHAR(10)),
       MO.ID, MO.CODIGO, MO.NOMBRE, MO.DESCRIPCION,
       MO.UNIDAD_MEDIDA_ID, U.NOMBRE,
       MO.CATEGORIA_ID,
       P.COSTO_UNITARIO, CAST(NULL AS NUMERIC(15,2)),
       CAST(NULL AS NUMERIC(15,2)),
       P.COSTO_UNITARIO, P.FECHA_VIGENCIA, MO.ACTIVO,
       (SELECT MIN(PP.FECHA_VIGENCIA) FROM PRECIOS_PROGRAMADOS PP
         WHERE PP.MANO_OBRA_ID = MO.ID AND PP.ESTADO = 'pendiente')
  FROM MANO_OBRA MO
  JOIN UNIDADES_MEDIDA U ON U.ID = MO.UNIDAD_MEDIDA_ID
  LEFT JOIN MANO_OBRA_PRECIOS P
    ON P.MANO_OBRA_ID = MO.ID AND P.ACTIVO = TRUE
UNION ALL
SELECT CAST('maquina' AS VARCHAR(10)),
       Q.ID, Q.CODIGO, Q.NOMBRE, Q.DESCRIPCION,
       CAST(NULL AS INTEGER), CAST('hora' AS VARCHAR(20)),
       CAST(NULL AS INTEGER),
       CAST(NULL AS NUMERIC(15,2)), CAST(NULL AS NUMERIC(15,2)),
       P.COSTO_HORA,
       P.COSTO_HORA, P.FECHA_VIGENCIA, Q.ACTIVO,
       (SELECT MIN(PP.FECHA_VIGENCIA) FROM PRECIOS_PROGRAMADOS PP
         WHERE PP.MAQUINA_ID = Q.ID AND PP.ESTADO = 'pendiente')
  FROM MAQUINAS Q
  LEFT JOIN MAQUINAS_PRECIOS P
    ON P.MAQUINA_ID = Q.ID AND P.ACTIVO = TRUE;

COMMIT;

/* ----------------------------------------------------------------------------
   4. Permisos. Solo lectura para el backend.
   ---------------------------------------------------------------------------- */
GRANT SELECT ON V_SOLICITUDES TO ROL_BACKEND;
GRANT SELECT ON V_COTIZACIONES TO ROL_BACKEND;
GRANT SELECT ON V_CATALOGO_ITEMS TO ROL_BACKEND;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

     SELECT COUNT(*) FROM V_SOLICITUDES;      -- igual que SOLICITUDES
     SELECT COUNT(*) FROM V_COTIZACIONES;     -- igual que COTIZACIONES
     SELECT TIPO, COUNT(*) FROM V_CATALOGO_ITEMS GROUP BY TIPO;
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 19_vista_catalogo_categoria.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 19: V_CATALOGO_ITEMS con el nombre de la categoria
   ----------------------------------------------------------------------------
   El listado de mano de obra muestra la categoria por nombre y la vista de
   la 18 solo traia CATEGORIA_ID. Se rehace con CATEGORIA_NOMBRE, nulo en
   materiales y maquinas. CREATE OR ALTER conserva el GRANT de la 18.
   ============================================================================ */

CREATE OR ALTER VIEW V_CATALOGO_ITEMS AS
SELECT CAST('material' AS VARCHAR(10)) AS TIPO,
       M.ID, M.CODIGO, M.NOMBRE, M.DESCRIPCION,
       M.UNIDAD_MEDIDA_ID, U.NOMBRE AS UNIDAD_MEDIDA,
       CAST(NULL AS INTEGER) AS CATEGORIA_ID,
       CAST(NULL AS VARCHAR(120)) AS CATEGORIA_NOMBRE,
       P.COSTO_UNITARIO, P.PRECIO_UNITARIO,
       CAST(NULL AS NUMERIC(15,2)) AS COSTO_HORA,
       P.COSTO_UNITARIO AS COSTO, P.FECHA_VIGENCIA, M.ACTIVO,
       (SELECT MIN(PP.FECHA_VIGENCIA) FROM PRECIOS_PROGRAMADOS PP
         WHERE PP.MATERIAL_ID = M.ID AND PP.ESTADO = 'pendiente')
         AS PROGRAMADO_FECHA
  FROM MATERIALES M
  JOIN UNIDADES_MEDIDA U ON U.ID = M.UNIDAD_MEDIDA_ID
  LEFT JOIN MATERIALES_PRECIOS P
    ON P.MATERIAL_ID = M.ID AND P.ACTIVO = TRUE
UNION ALL
SELECT CAST('mano_obra' AS VARCHAR(10)),
       MO.ID, MO.CODIGO, MO.NOMBRE, MO.DESCRIPCION,
       MO.UNIDAD_MEDIDA_ID, U.NOMBRE,
       MO.CATEGORIA_ID, CAT.NOMBRE,
       P.COSTO_UNITARIO, CAST(NULL AS NUMERIC(15,2)),
       CAST(NULL AS NUMERIC(15,2)),
       P.COSTO_UNITARIO, P.FECHA_VIGENCIA, MO.ACTIVO,
       (SELECT MIN(PP.FECHA_VIGENCIA) FROM PRECIOS_PROGRAMADOS PP
         WHERE PP.MANO_OBRA_ID = MO.ID AND PP.ESTADO = 'pendiente')
  FROM MANO_OBRA MO
  JOIN MANO_OBRA_CATEGORIA CAT ON CAT.ID = MO.CATEGORIA_ID
  JOIN UNIDADES_MEDIDA U ON U.ID = MO.UNIDAD_MEDIDA_ID
  LEFT JOIN MANO_OBRA_PRECIOS P
    ON P.MANO_OBRA_ID = MO.ID AND P.ACTIVO = TRUE
UNION ALL
SELECT CAST('maquina' AS VARCHAR(10)),
       Q.ID, Q.CODIGO, Q.NOMBRE, Q.DESCRIPCION,
       CAST(NULL AS INTEGER), CAST('hora' AS VARCHAR(20)),
       CAST(NULL AS INTEGER), CAST(NULL AS VARCHAR(120)),
       CAST(NULL AS NUMERIC(15,2)), CAST(NULL AS NUMERIC(15,2)),
       P.COSTO_HORA,
       P.COSTO_HORA, P.FECHA_VIGENCIA, Q.ACTIVO,
       (SELECT MIN(PP.FECHA_VIGENCIA) FROM PRECIOS_PROGRAMADOS PP
         WHERE PP.MAQUINA_ID = Q.ID AND PP.ESTADO = 'pendiente')
  FROM MAQUINAS Q
  LEFT JOIN MAQUINAS_PRECIOS P
    ON P.MAQUINA_ID = Q.ID AND P.ACTIVO = TRUE;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

     SELECT TIPO, COUNT(*), COUNT(CATEGORIA_NOMBRE)
       FROM V_CATALOGO_ITEMS GROUP BY TIPO;

   CATEGORIA_NOMBRE solo tiene valor en mano_obra, en todas sus filas.
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 20_vistas_totales.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 20: vistas de totales
   ----------------------------------------------------------------------------
   Los totales de los dashboards y de los reportes estaban escritos como
   consultas en el backend. Pasan a vistas: los dashboards siempre muestran el
   mes en curso, asi que sus vistas lo toman de V_PERIODO_ACTUAL y no reciben
   fechas; el backend solo filtra por usuario. Los reportes usan un rango libre:
   V_COTIZACIONES_DIA las agrupa por dia y el servicio suma el rango.

   Igual que la 18: sin parametros y sin reglas de negocio. La tasa de
   aprobacion la calcula el servicio.

   Todo en ASCII.
   ============================================================================ */

/* ----------------------------------------------------------------------------
   1. V_PERIODO_ACTUAL: el mes en curso, escrito una sola vez. MES_HASTA es el
   primer dia del mes siguiente: los filtros usan >= desde y < hasta.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_PERIODO_ACTUAL AS
SELECT CAST(DATEADD(1 - EXTRACT(DAY FROM CURRENT_DATE) DAY TO CURRENT_DATE)
            AS TIMESTAMP) AS MES_DESDE,
       CAST(DATEADD(1 MONTH TO DATEADD(1 - EXTRACT(DAY FROM CURRENT_DATE)
            DAY TO CURRENT_DATE)) AS TIMESTAMP) AS MES_HASTA
  FROM RDB$DATABASE;

/* ----------------------------------------------------------------------------
   2. V_TRABAJO_USUARIO: lo que cada usuario tiene en la mesa. POR_COTIZAR es
   la cola comun, igual para todos. POR_APROBAR y DIAS_MAS_ANTIGUA cuentan las
   pendientes que el usuario no elaboro: nadie revisa lo propio.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_TRABAJO_USUARIO AS
SELECT U.ID AS USUARIO_ID,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM V_SOLICITUDES S
         WHERE S.ESTADO = 'recibida' AND S.TIENE_COTIZACION = FALSE)
         AS POR_COTIZAR,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO = 'borrador')
         AS MIS_BORRADORES,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO = 'pendiente')
         AS EN_APROBACION,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO = 'aprobada'
           AND C.FECHA_ENVIO IS NULL)
         AS POR_ENVIAR,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ESTADO = 'pendiente' AND C.ELABORADA_POR <> U.ID)
         AS POR_APROBAR,
       (SELECT CAST(COALESCE(MAX(C.DIAS_EN_ESTADO), 0) AS INTEGER)
          FROM V_COTIZACIONES C
         WHERE C.ESTADO = 'pendiente' AND C.ELABORADA_POR <> U.ID)
         AS DIAS_MAS_ANTIGUA
  FROM USUARIOS U;

/* ----------------------------------------------------------------------------
   3. V_RESUMEN_MES: el mes de toda la empresa. Rechazadas por
   FECHA_MODIFICACION: no hay fecha propia de rechazo.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_RESUMEN_MES AS
SELECT P.MES_DESDE AS DESDE, P.MES_HASTA AS HASTA,
       (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
          FROM COTIZACIONES C
         WHERE C.ESTADO <> 'borrador'
           AND C.FECHA_ELABORACION >= P.MES_DESDE
           AND C.FECHA_ELABORACION < P.MES_HASTA)
         AS COTIZADO_MES,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ESTADO IN ('aprobada', 'enviada')
           AND C.FECHA_APROBACION >= P.MES_DESDE
           AND C.FECHA_APROBACION < P.MES_HASTA)
         AS APROBADAS_MES,
       (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
          FROM COTIZACIONES C
         WHERE C.ESTADO IN ('aprobada', 'enviada')
           AND C.FECHA_APROBACION >= P.MES_DESDE
           AND C.FECHA_APROBACION < P.MES_HASTA)
         AS MONTO_APROBADO_MES,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ESTADO = 'rechazada'
           AND C.FECHA_MODIFICACION >= P.MES_DESDE
           AND C.FECHA_MODIFICACION < P.MES_HASTA)
         AS RECHAZADAS_MES,
       (SELECT CAST(COALESCE(AVG(C.DIAS_RESPUESTA), 0) AS INTEGER)
          FROM V_COTIZACIONES C
         WHERE C.ESTADO IN ('aprobada', 'enviada')
           AND C.FECHA_APROBACION >= P.MES_DESDE
           AND C.FECHA_APROBACION < P.MES_HASTA)
         AS RESPUESTA_MEDIA,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
          JOIN ROLES R ON R.ID = U.ROL_ID
         WHERE R.CODIGO = 'asesor' AND U.ACTIVO)
         AS ASESORES_ACTIVOS
  FROM V_PERIODO_ACTUAL P;

/* ----------------------------------------------------------------------------
   4. V_ASESORES_MES: el mes de cada asesor. ESPERANDO_COTIZACION no depende
   del mes: son las suyas que siguen sin cotizacion aprobada ni enviada.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_ASESORES_MES AS
SELECT U.ID AS ASESOR_ID, U.NOMBRE AS ASESOR_NOMBRE, U.ACTIVO,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM SOLICITUDES S
         WHERE S.ASESOR_ID = U.ID
           AND S.FECHA_CAPTURA >= P.MES_DESDE
           AND S.FECHA_CAPTURA < P.MES_HASTA)
         AS SOLICITUDES_MES,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM SOLICITUDES S
         WHERE S.ASESOR_ID = U.ID
           AND S.ESTADO IN ('recibida', 'en_cotizacion')
           AND NOT EXISTS (SELECT 1 FROM COTIZACIONES X
                            WHERE X.SOLICITUD_ID = S.ID
                              AND X.ESTADO IN ('aprobada', 'enviada')))
         AS ESPERANDO_COTIZACION,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM V_COTIZACIONES C
         WHERE C.ASESOR_ID = U.ID AND C.ESTADO IN ('aprobada', 'enviada')
           AND C.FECHA_APROBACION >= P.MES_DESDE
           AND C.FECHA_APROBACION < P.MES_HASTA)
         AS APROBADAS_MES,
       (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
          FROM V_COTIZACIONES C
         WHERE C.ASESOR_ID = U.ID AND C.ESTADO IN ('aprobada', 'enviada')
           AND C.FECHA_APROBACION >= P.MES_DESDE
           AND C.FECHA_APROBACION < P.MES_HASTA)
         AS MONTO_APROBADO_MES
  FROM USUARIOS U
  JOIN ROLES R ON R.ID = U.ROL_ID
  CROSS JOIN V_PERIODO_ACTUAL P
 WHERE R.CODIGO = 'asesor';

/* ----------------------------------------------------------------------------
   5. V_COTIZACIONES_POR_ESTADO: todas, con el orden en que se presentan.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_COTIZACIONES_POR_ESTADO AS
SELECT ESTADO,
       CASE ESTADO WHEN 'borrador' THEN 1 WHEN 'pendiente' THEN 2
                   WHEN 'aprobada' THEN 3 WHEN 'enviada' THEN 4 ELSE 5 END
         AS ORDEN,
       CAST(COUNT(*) AS INTEGER) AS CANTIDAD,
       CAST(COALESCE(SUM(MONTO_TOTAL), 0) AS NUMERIC(18,2)) AS MONTO
  FROM COTIZACIONES
 GROUP BY ESTADO;

/* ----------------------------------------------------------------------------
   6. V_CUENTAS_RESUMEN: las cuentas, sin el usuario Sistema (migracion 13),
   que existe solo para firmar lo que el servidor hace solo.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_CUENTAS_RESUMEN AS
SELECT (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
         WHERE U.ACTIVO AND U.CORREO <> 'sistema@anovo.local')
         AS USUARIOS_ACTIVOS,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
         WHERE NOT U.ACTIVO AND U.CORREO <> 'sistema@anovo.local')
         AS USUARIOS_INACTIVOS,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
         WHERE U.ACTIVO AND U.DEBE_CAMBIAR_CLAVE)
         AS CLAVE_PENDIENTE,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM AUDITORIA A
         WHERE A.ENTIDAD = 'USUARIOS'
           AND A.FECHA >= P.MES_DESDE AND A.FECHA < P.MES_HASTA)
         AS CAMBIOS_MES
  FROM V_PERIODO_ACTUAL P;

/* ----------------------------------------------------------------------------
   7. V_AUDITORIA: la bitacora con el nombre de quien hizo cada cambio.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_AUDITORIA AS
SELECT A.ID, A.FECHA, A.USUARIO_ID, COALESCE(U.NOMBRE, '') AS USUARIO_NOMBRE,
       A.ACCION, A.ENTIDAD, A.ENTIDAD_ID, A.DETALLE
  FROM AUDITORIA A
  LEFT JOIN USUARIOS U ON U.ID = A.USUARIO_ID;

/* ----------------------------------------------------------------------------
   8. V_SEGUIMIENTO_ASESOR: las solicitudes como las ve el asesor (HU-03): el
   estado de la cotizacion si ya se aprobo o envio, si no el de la solicitud.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_SEGUIMIENTO_ASESOR AS
SELECT S.ID, S.ASESOR_ID, S.FECHA_CAPTURA, S.CLIENTE_NOMBRE, S.DESCRIPCION,
       COALESCE(K.ESTADO, S.ESTADO) AS ESTADO,
       K.ID AS COTIZACION_ID, K.MONTO_TOTAL AS MONTO_APROBADO
  FROM V_SOLICITUDES S
  LEFT JOIN COTIZACIONES K ON K.ID =
       (SELECT MAX(X.ID) FROM COTIZACIONES X
         WHERE X.SOLICITUD_ID = S.ID
           AND X.ESTADO IN ('aprobada', 'enviada'));

/* ----------------------------------------------------------------------------
   9. V_COTIZACIONES_DIA: las cotizaciones agrupadas por dia de elaboracion,
   estado, asesor y tipo de trabajo. Los reportes piden las filas de su rango
   y el servicio las suma. SUMA_DIAS_RESPUESTA y CON_RESPUESTA dan el promedio
   exacto sin promediar promedios.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_COTIZACIONES_DIA AS
SELECT CAST(FECHA_ELABORACION AS DATE) AS FECHA,
       CAST(EXTRACT(YEAR FROM FECHA_ELABORACION) AS INTEGER) AS ANIO,
       CAST(EXTRACT(MONTH FROM FECHA_ELABORACION) AS INTEGER) AS MES,
       ESTADO, ASESOR_ID, ASESOR_NOMBRE, TIPO_TRABAJO_ID, TIPO_TRABAJO_NOMBRE,
       CAST(COUNT(*) AS INTEGER) AS CANTIDAD,
       CAST(COALESCE(SUM(MONTO_TOTAL), 0) AS NUMERIC(18,2)) AS MONTO_TOTAL,
       CAST(SUM(CASE WHEN ESTADO IN ('aprobada', 'enviada') THEN 1 ELSE 0 END)
            AS INTEGER) AS APROBADAS,
       CAST(SUM(CASE WHEN ESTADO = 'rechazada' THEN 1 ELSE 0 END)
            AS INTEGER) AS RECHAZADAS,
       CAST(COALESCE(SUM(CASE WHEN ESTADO IN ('aprobada', 'enviada')
            THEN MONTO_TOTAL ELSE 0 END), 0) AS NUMERIC(18,2))
            AS MONTO_APROBADO,
       CAST(COALESCE(SUM(DIAS_RESPUESTA), 0) AS INTEGER) AS SUMA_DIAS_RESPUESTA,
       CAST(COUNT(DIAS_RESPUESTA) AS INTEGER) AS CON_RESPUESTA
  FROM V_COTIZACIONES
 GROUP BY 1, 2, 3, 4, 5, 6, 7, 8;

COMMIT;

/* ----------------------------------------------------------------------------
   10. Permisos. Solo lectura para el backend.
   ---------------------------------------------------------------------------- */
GRANT SELECT ON V_PERIODO_ACTUAL TO ROL_BACKEND;
GRANT SELECT ON V_TRABAJO_USUARIO TO ROL_BACKEND;
GRANT SELECT ON V_RESUMEN_MES TO ROL_BACKEND;
GRANT SELECT ON V_ASESORES_MES TO ROL_BACKEND;
GRANT SELECT ON V_COTIZACIONES_POR_ESTADO TO ROL_BACKEND;
GRANT SELECT ON V_CUENTAS_RESUMEN TO ROL_BACKEND;
GRANT SELECT ON V_AUDITORIA TO ROL_BACKEND;
GRANT SELECT ON V_SEGUIMIENTO_ASESOR TO ROL_BACKEND;
GRANT SELECT ON V_COTIZACIONES_DIA TO ROL_BACKEND;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

     SELECT * FROM V_PERIODO_ACTUAL;
     SELECT * FROM V_TRABAJO_USUARIO WHERE USUARIO_ID = 2;
     SELECT * FROM V_RESUMEN_MES;
     SELECT SUM(CANTIDAD) FROM V_COTIZACIONES_DIA;   -- igual que COTIZACIONES
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 21_trabajo_usuario_monto.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 21: V_TRABAJO_USUARIO con el monto por aprobar
   ----------------------------------------------------------------------------
   La bandeja del supervisor muestra tres cifras: pendientes, dias de la mas
   antigua y monto en espera. La vista de la 20 traia las dos primeras; se
   rehace con MONTO_POR_APROBAR para que el resumen de la bandeja salga de la
   vista y no de una consulta en el backend. CREATE OR ALTER conserva el GRANT.
   ============================================================================ */

CREATE OR ALTER VIEW V_TRABAJO_USUARIO AS
SELECT U.ID AS USUARIO_ID,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM V_SOLICITUDES S
         WHERE S.ESTADO = 'recibida' AND S.TIENE_COTIZACION = FALSE)
         AS POR_COTIZAR,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO = 'borrador')
         AS MIS_BORRADORES,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO = 'pendiente')
         AS EN_APROBACION,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO = 'aprobada'
           AND C.FECHA_ENVIO IS NULL)
         AS POR_ENVIAR,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM COTIZACIONES C
         WHERE C.ESTADO = 'pendiente' AND C.ELABORADA_POR <> U.ID)
         AS POR_APROBAR,
       (SELECT CAST(COALESCE(MAX(C.DIAS_EN_ESTADO), 0) AS INTEGER)
          FROM V_COTIZACIONES C
         WHERE C.ESTADO = 'pendiente' AND C.ELABORADA_POR <> U.ID)
         AS DIAS_MAS_ANTIGUA,
       (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
          FROM COTIZACIONES C
         WHERE C.ESTADO = 'pendiente' AND C.ELABORADA_POR <> U.ID)
         AS MONTO_POR_APROBAR
  FROM USUARIOS U;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

     SELECT POR_APROBAR, DIAS_MAS_ANTIGUA, MONTO_POR_APROBAR
       FROM V_TRABAJO_USUARIO WHERE USUARIO_ID = 3;

   Igual al resumen de la bandeja del supervisor.
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 22_vistas_sin_binarios_y_permisos.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 22: vistas sin columnas binarias y matriz de permisos
   ----------------------------------------------------------------------------
   Los listados de adjuntos y de consentimientos no traen el contenido ni la
   firma: se leen de vistas sin esas columnas. La matriz rol-permiso deja de
   ser un join en el backend. Igual que la 18 y la 20: sin parametros y sin
   reglas de negocio.

   Todo en ASCII.
   ============================================================================ */

/* ----------------------------------------------------------------------------
   1. V_SOLICITUD_ADJUNTOS: los adjuntos sin CONTENIDO ni CONTENIDO_JSON. El
   contenido se pide aparte, uno por uno.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_SOLICITUD_ADJUNTOS AS
SELECT ID, SOLICITUD_ID, UUID_LOCAL, TIPO, NOMBRE_ARCHIVO, MIME,
       TAMANO_BYTES, ACTIVO, FECHA_CREACION
  FROM SOLICITUD_ADJUNTOS;

/* ----------------------------------------------------------------------------
   2. V_CONSENTIMIENTOS: el historial de consentimiento sin la imagen de la
   firma (Ley 8968: la firma solo sale cuando se pide).
   ---------------------------------------------------------------------------- */
CREATE VIEW V_CONSENTIMIENTOS AS
SELECT ID, CLIENTE_ID, CLIENTE_CONTACTO_ID, ACCION, VERSION_TEXTO, FECHA,
       FIRMANTE_NOMBRE, FIRMANTE_IDENTIFICACION, FIRMA_MIME, ORIGEN
  FROM CLIENTE_CONSENTIMIENTO_HISTORIAL;

/* ----------------------------------------------------------------------------
   3. V_PERMISOS_ROLES: la matriz rol-permiso con los codigos.
   ---------------------------------------------------------------------------- */
CREATE VIEW V_PERMISOS_ROLES AS
SELECT R.CODIGO AS ROL, P.CODIGO AS PERMISO
  FROM ROLES_PERMISOS RP
  JOIN ROLES R ON R.ID = RP.ROL_ID
  JOIN PERMISOS P ON P.ID = RP.PERMISO_ID;

COMMIT;

/* ----------------------------------------------------------------------------
   4. Permisos. Solo lectura para el backend.
   ---------------------------------------------------------------------------- */
GRANT SELECT ON V_SOLICITUD_ADJUNTOS TO ROL_BACKEND;
GRANT SELECT ON V_CONSENTIMIENTOS TO ROL_BACKEND;
GRANT SELECT ON V_PERMISOS_ROLES TO ROL_BACKEND;

COMMIT;

/* ----------------------------------------------------------------------------
   COMPROBACION

     SELECT COUNT(*) FROM V_SOLICITUD_ADJUNTOS;   -- igual que la tabla
     SELECT COUNT(*) FROM V_CONSENTIMIENTOS;      -- igual que la tabla
     SELECT COUNT(*) FROM V_PERMISOS_ROLES;       -- igual que ROLES_PERMISOS
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 23_empresa_sin_usuario.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 23: EMPRESA sin relacion con USUARIOS
   ----------------------------------------------------------------------------
   EMPRESA guarda los datos de Anovo para el encabezado de la cotizacion y no
   se relaciona con las cuentas de usuario. MODIFICADO_POR no lo leia ni lo
   escribia nadie: quien cambia los datos de la empresa queda en AUDITORIA por
   TR_EMPRESA_AUD, que toma el usuario del contexto de la sesion.

   La clave foranea se creo sin nombre (INTEG_nn), por eso se busca antes de
   quitar la columna; Firebird no deja borrar una columna con una restriccion.

   Todo en ASCII.
   ============================================================================ */

SET TERM ^ ;

EXECUTE BLOCK AS
  DECLARE VARIABLE V_FK VARCHAR(63);
BEGIN
  SELECT TRIM(RC.RDB$CONSTRAINT_NAME)
    FROM RDB$RELATION_CONSTRAINTS RC
    JOIN RDB$INDEX_SEGMENTS S ON S.RDB$INDEX_NAME = RC.RDB$INDEX_NAME
   WHERE RC.RDB$RELATION_NAME = 'EMPRESA'
     AND RC.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY'
     AND S.RDB$FIELD_NAME = 'MODIFICADO_POR'
    INTO :V_FK;
  IF (V_FK IS NOT NULL) THEN
    EXECUTE STATEMENT 'ALTER TABLE EMPRESA DROP CONSTRAINT ' || V_FK;
END^

SET TERM ; ^

COMMIT;

ALTER TABLE EMPRESA DROP MODIFICADO_POR;

COMMIT;

/* ----------------------------------------------------------------------------
   Verificacion:
     SELECT RDB$FIELD_NAME FROM RDB$RELATION_FIELDS
      WHERE RDB$RELATION_NAME = 'EMPRESA';          -- sin MODIFICADO_POR
     SELECT * FROM EMPRESA;                         -- la fila ID = 1 intacta
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 24_indices_duplicados.sql
   ############################################################################ */

/* ============================================================================
   Anovo - Migracion 24: quitar indices duplicados
   ----------------------------------------------------------------------------
   Firebird crea un indice por cada PRIMARY KEY, FOREIGN KEY y UNIQUE. Estos
   indices repetian el de una clave foranea: trece con las mismas columnas y
   IDX_ROLPERM_PERMISO con la primera columna de FK_ROLPERM_PERMISO
   (PERMISO_ID, AMBITO), que el optimizador usa tambien para buscar solo por
   PERMISO_ID. No aceleraban ninguna consulta y si cada escritura.

   Se quedan los que combinan columnas o atienden estado y fecha:
   *_MOD, *_PRECIO_ACTIVO, IDX_PRECIOPROG_PENDIENTE, IDX_CLAVES_USUARIO_ACTIVO,
   IDX_COTIZ_ESTADO, IDX_COTIZ_FECHA, IDX_AUDITORIA_* y
   UQ_UNIDADES_MEDIDA_NOMBRE.

   Todo en ASCII.
   ============================================================================ */

DROP INDEX IDX_CONTACTOS_CLIENTE;
DROP INDEX IDX_CONSHIST_CLIENTE;
DROP INDEX IDX_SOLICITUDES_ASESOR;
DROP INDEX IDX_SOLICITUDES_CLIENTE;
DROP INDEX IDX_ADJUNTOS_SOLICITUD;
DROP INDEX IDX_MEDIDAS_SOLICITUD;
DROP INDEX IDX_MANO_OBRA_CATEGORIA;
DROP INDEX IDX_MATERIALES_UNIDAD;
DROP INDEX IDX_MANO_OBRA_UNIDAD;
DROP INDEX IDX_PRECIOPROG_MATERIAL;
DROP INDEX IDX_PRECIOPROG_MANO_OBRA;
DROP INDEX IDX_PRECIOPROG_MAQUINA;
DROP INDEX IDX_DETALLE_COTIZ;
DROP INDEX IDX_ROLPERM_PERMISO;

COMMIT;

/* ----------------------------------------------------------------------------
   Verificacion:
     SELECT RDB$INDEX_NAME FROM RDB$INDICES I
      WHERE COALESCE(I.RDB$SYSTEM_FLAG, 0) = 0
        AND NOT EXISTS (SELECT 1 FROM RDB$RELATION_CONSTRAINTS C
                         WHERE C.RDB$INDEX_NAME = I.RDB$INDEX_NAME);
     -- quedan 14: los 13 que combinan columnas o atienden estado y fecha,
     -- y UQ_UNIDADES_MEDIDA_NOMBRE
   ---------------------------------------------------------------------------- */


/* ############################################################################
   TRAMO 25_permisos_por_usuario.sql
   ############################################################################ */

/* Anovo - Migracion 25: permisos por usuario sobre el rol base.
   Excepciones otorgado/quitado con motivo, ambito en USUARIOS y vistas
   para Usuarios y Roles. Todo en ASCII. */

SELECT RDB$SET_CONTEXT('USER_SESSION', 'USUARIO_ID',
  (SELECT ID FROM USUARIOS WHERE CORREO = 'sistema@anovo.local'))
  FROM RDB$DATABASE;
SELECT RDB$SET_CONTEXT('USER_SESSION', 'DETALLE',
  'migracion 25: ambito del rol') FROM RDB$DATABASE;

ALTER TABLE USUARIOS
  ADD AMBITO D_AMBITO DEFAULT 'negocio' NOT NULL;

COMMIT;

UPDATE USUARIOS SET AMBITO = 'administracion'
 WHERE ROL_ID IN (SELECT ID FROM ROLES WHERE AMBITO = 'administracion');

COMMIT;

ALTER TABLE USUARIOS
  ADD CONSTRAINT UQ_USUARIOS_ID_AMBITO UNIQUE (ID, AMBITO);
ALTER TABLE USUARIOS
  ADD CONSTRAINT FK_USUARIOS_ROL_AMBITO FOREIGN KEY (ROL_ID, AMBITO)
    REFERENCES ROLES (ID, AMBITO);

COMMENT ON COLUMN USUARIOS.AMBITO IS
  'Copia del ambito del rol. Decide que permisos puede recibir la persona.';

CREATE TABLE USUARIOS_PERMISOS (
  USUARIO_ID     INTEGER       NOT NULL,
  PERMISO_ID     INTEGER       NOT NULL,
  AMBITO         D_AMBITO      NOT NULL,
  TIPO           VARCHAR(10)   NOT NULL,
  MOTIVO         D_DESCRIPCION NOT NULL,
  FECHA_CREACION D_TIMESTAMP,
  CONSTRAINT PK_USUARIOS_PERMISOS PRIMARY KEY (USUARIO_ID, PERMISO_ID),
  CONSTRAINT CK_USUPERM_TIPO CHECK (TIPO IN ('otorgado', 'quitado')),
  CONSTRAINT FK_USUPERM_USUARIO FOREIGN KEY (USUARIO_ID, AMBITO)
    REFERENCES USUARIOS (ID, AMBITO),
  CONSTRAINT FK_USUPERM_PERMISO FOREIGN KEY (PERMISO_ID, AMBITO)
    REFERENCES PERMISOS (ID, AMBITO)
);

COMMENT ON TABLE USUARIOS_PERMISOS IS
  'Excepciones de una persona sobre los permisos de su rol. Insert o delete, sin update.';

COMMIT;

SET TERM ^ ;

CREATE TRIGGER TR_USUARIOS_PERMISOS_AUD FOR USUARIOS_PERMISOS
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_ACCION  VARCHAR(50);
  DECLARE VARIABLE V_ID      INTEGER;
  DECLARE VARIABLE V_PERMISO INTEGER;
  DECLARE VARIABLE V_TIPO    VARCHAR(10);
  DECLARE VARIABLE V_DETALLE VARCHAR(500);
BEGIN
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  V_DETALLE = RDB$GET_CONTEXT('USER_SESSION', 'DETALLE');
  IF (INSERTING) THEN BEGIN V_ACCION = 'insertar';   V_ID = NEW.USUARIO_ID; V_PERMISO = NEW.PERMISO_ID; V_TIPO = NEW.TIPO; END
  ELSE IF (UPDATING) THEN BEGIN V_ACCION = 'actualizar'; V_ID = NEW.USUARIO_ID; V_PERMISO = NEW.PERMISO_ID; V_TIPO = NEW.TIPO; END
  ELSE BEGIN V_ACCION = 'borrar'; V_ID = OLD.USUARIO_ID; V_PERMISO = OLD.PERMISO_ID; V_TIPO = OLD.TIPO; END
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'USUARIOS_PERMISOS', :V_ID,
          COALESCE(:V_DETALLE, :V_TIPO || ' permiso ' || :V_PERMISO));
END^

SET TERM ; ^

CREATE VIEW V_USUARIOS AS
SELECT U.ID, U.CORREO, U.NOMBRE, U.ROL_ID, R.CODIGO AS ROL,
       R.NOMBRE AS ROL_NOMBRE, U.AMBITO, U.ACTIVO, U.DEBE_CAMBIAR_CLAVE,
       U.FECHA_CREACION, U.FECHA_MODIFICACION,
       (SELECT MAX(C.FECHA_CAMBIO) FROM USUARIOS_CLAVES C
         WHERE C.USUARIO_ID = U.ID AND C.ACTIVO = TRUE) AS FECHA_CLAVE,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS_PERMISOS P
         WHERE P.USUARIO_ID = U.ID) AS EXCEPCIONES
  FROM USUARIOS U
  JOIN ROLES R ON R.ID = U.ROL_ID;

CREATE VIEW V_ROLES AS
SELECT R.ID, R.CODIGO, R.NOMBRE, R.AMBITO,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
         WHERE U.ROL_ID = R.ID AND U.ACTIVO = TRUE) AS USUARIOS_ACTIVOS
  FROM ROLES R;

CREATE VIEW V_USUARIOS_PERMISOS AS
SELECT UP.USUARIO_ID, UP.PERMISO_ID, P.CODIGO AS PERMISO, P.NOMBRE,
       P.MODULO, UP.TIPO, UP.MOTIVO, UP.FECHA_CREACION
  FROM USUARIOS_PERMISOS UP
  JOIN PERMISOS P ON P.ID = UP.PERMISO_ID;

COMMIT;

GRANT SELECT, INSERT, DELETE ON USUARIOS_PERMISOS TO ROL_BACKEND;
GRANT SELECT ON V_USUARIOS          TO ROL_BACKEND;
GRANT SELECT ON V_ROLES             TO ROL_BACKEND;
GRANT SELECT ON V_USUARIOS_PERMISOS TO ROL_BACKEND;

GRANT INSERT ON AUDITORIA TO TRIGGER TR_USUARIOS_PERMISOS_AUD;
GRANT USAGE ON EXCEPTION E_AUDITORIA_SIN_USUARIO TO TRIGGER TR_USUARIOS_PERMISOS_AUD;

SELECT RDB$SET_CONTEXT('USER_SESSION', 'DETALLE', NULL) FROM RDB$DATABASE;
SELECT RDB$SET_CONTEXT('USER_SESSION', 'USUARIO_ID', NULL) FROM RDB$DATABASE;

COMMIT;

/* ############################################################################
   TRAMO 26_cambios_de_cuentas.sql
   ############################################################################ */

/* Anovo - Migracion 26: los cambios de cuentas del mes cuentan tambien las
   claves, la matriz de roles y los permisos por persona (migracion 25), no
   solo la tabla USUARIOS. Todo en ASCII. */

ALTER VIEW V_CUENTAS_RESUMEN AS
SELECT (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
         WHERE U.ACTIVO AND U.CORREO <> 'sistema@anovo.local')
         AS USUARIOS_ACTIVOS,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
         WHERE NOT U.ACTIVO AND U.CORREO <> 'sistema@anovo.local')
         AS USUARIOS_INACTIVOS,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
         WHERE U.ACTIVO AND U.DEBE_CAMBIAR_CLAVE)
         AS CLAVE_PENDIENTE,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM AUDITORIA A
         WHERE A.ENTIDAD IN ('USUARIOS', 'USUARIOS_CLAVES', 'ROLES_PERMISOS',
                             'USUARIOS_PERMISOS')
           AND A.FECHA >= P.MES_DESDE AND A.FECHA < P.MES_HASTA)
         AS CAMBIOS_MES
  FROM V_PERIODO_ACTUAL P;

COMMIT;

/* ############################################################################
   TRAMO 27_montos_no_nulos.sql
   ############################################################################ */

/* Anovo - Migracion 27: NOT NULL en la columna de los montos D_MONTO.
   El dominio ya lo exige, pero MVCEntGen solo mira la columna y generaba
   NullableCurrency; con NULL explicito el DEFAULT 0 no actuaba. Todo en ASCII. */

ALTER TABLE COTIZACIONES ALTER COLUMN SUBTOTAL_MATERIALES SET NOT NULL;
