CREATE TRIGGER TR_AUDITORIA_BI_DEF FOR AUDITORIA ACTIVE BEFORE INSERT POSITION 0 AS
BEGIN
  IF (NEW.FECHA IS NULL) THEN NEW.FECHA = CURRENT_TIMESTAMP;
END^

