   Verificacion:
     SELECT COUNT(*) FROM USUARIOS_DISPOSITIVOS;                -- 0
     SELECT * FROM V_USUARIOS_DISPOSITIVOS;                     -- sin filas
     SELECT RDB$TRIGGER_NAME FROM RDB$TRIGGERS
      WHERE RDB$RELATION_NAME = 'USUARIOS_DISPOSITIVOS';        -- 3 disparadores
     SELECT * FROM V_VERSION_ESQUEMA;                           -- 40
   ---------------------------------------------------------------------------- */


