/* ---------------------------------------------------------------------------
   2. Catalogos. El ID es fijo: el backend nombra cada valor por su ID.
   --------------------------------------------------------------------------- */

CREATE TABLE ESTADOS_COTIZACION (
  ID       INTEGER NOT NULL,
  CODIGO   VARCHAR(20) NOT NULL,
  NOMBRE   D_NOMBRE NOT NULL,
  ORDEN    SMALLINT DEFAULT 0 NOT NULL,
  ACTIVO   D_BOOLEANO,
  CONSTRAINT PK_ESTADOS_COTIZACION PRIMARY KEY (ID),
  CONSTRAINT UQ_ESTADOS_COTIZACION_CODIGO UNIQUE (CODIGO));

CREATE TABLE ESTADOS_SOLICITUD (
  ID       INTEGER NOT NULL,
  CODIGO   VARCHAR(20) NOT NULL,
  NOMBRE   D_NOMBRE NOT NULL,
  ORDEN    SMALLINT DEFAULT 0 NOT NULL,
