UPDATE COTIZACIONES K SET
  ESTADO_ID = (SELECT E.ID FROM ESTADOS_COTIZACION E
                WHERE E.CODIGO = IIF(K.ESTADO = 'pendiente', 'en_revision', K.ESTADO)),
  PLAZO_ENTREGA_UNIDAD_ID = (SELECT U.ID FROM UNIDADES_PLAZO U
                              WHERE U.CODIGO = K.PLAZO_ENTREGA_UNIDAD),
  GARANTIA_UNIDAD_ID = (SELECT U.ID FROM UNIDADES_PLAZO U
                         WHERE U.CODIGO = K.GARANTIA_UNIDAD);
UPDATE COTIZACION_ESTADOS H SET
  ESTADO_ID = (SELECT E.ID FROM ESTADOS_COTIZACION E
                WHERE E.CODIGO = IIF(H.ESTADO = 'pendiente', 'en_revision', H.ESTADO));
UPDATE SOLICITUDES S SET
  ESTADO_ID = (SELECT E.ID FROM ESTADOS_SOLICITUD E WHERE E.CODIGO = S.ESTADO);
UPDATE CLIENTES C SET
  CONSENTIMIENTO_ESTADO_ID = (SELECT E.ID FROM ESTADOS_CONSENTIMIENTO E
                               WHERE E.CODIGO = C.CONSENTIMIENTO_ESTADO);
UPDATE CLIENTE_CONTACTOS C SET
  CONSENTIMIENTO_ESTADO_ID = (SELECT E.ID FROM ESTADOS_CONSENTIMIENTO E
                               WHERE E.CODIGO = C.CONSENTIMIENTO_ESTADO);
UPDATE CLIENTE_CONSENTIMIENTO_HISTORIAL H SET
  ACCION_ID = (SELECT A.ID FROM ACCIONES_CONSENTIMIENTO A WHERE A.CODIGO = H.ACCION),
  ORIGEN_ID = (SELECT O.ID FROM ORIGENES_REGISTRO O WHERE O.CODIGO = H.ORIGEN);
UPDATE EMPRESA X SET
  PLAZO_ENTREGA_UNIDAD_ID = (SELECT U.ID FROM UNIDADES_PLAZO U
                              WHERE U.CODIGO = X.PLAZO_ENTREGA_UNIDAD),
  GARANTIA_UNIDAD_ID = (SELECT U.ID FROM UNIDADES_PLAZO U
                         WHERE U.CODIGO = X.GARANTIA_UNIDAD);
UPDATE COTIZACION_DETALLE D SET
  TIPO_LINEA_ID = (SELECT T.ID FROM TIPOS_LINEA T WHERE T.CODIGO = D.TIPO);
UPDATE PRECIOS_PROGRAMADOS P SET
  ESTADO_ID = (SELECT E.ID FROM ESTADOS_PRECIO E WHERE E.CODIGO = P.ESTADO),
  MATERIAL_PRECIO_ID = IIF(P.MATERIAL_ID IS NULL, NULL, P.PRECIO_ID),
  MANO_OBRA_PRECIO_ID = IIF(P.MANO_OBRA_ID IS NULL, NULL, P.PRECIO_ID),
  MAQUINA_PRECIO_ID = IIF(P.MAQUINA_ID IS NULL, NULL, P.PRECIO_ID);
UPDATE SOLICITUD_ADJUNTOS A SET
  TIPO_ADJUNTO_ID = (SELECT T.ID FROM TIPOS_ADJUNTO T WHERE T.CODIGO = A.TIPO);
UPDATE USUARIOS_PERMISOS P SET
  TIPO_EXCEPCION_ID = (SELECT T.ID FROM TIPOS_EXCEPCION T WHERE T.CODIGO = P.TIPO),
  AMBITO_ID = (SELECT A.ID FROM AMBITOS A WHERE A.CODIGO = P.AMBITO);
UPDATE USUARIOS_DISPOSITIVOS D SET
  MOTIVO_CIERRE_ID = (SELECT M.ID FROM MOTIVOS_CIERRE M WHERE M.CODIGO = D.MOTIVO);
UPDATE COTIZACION_ENVIOS E SET
  MODO_ENVIO_ID = (SELECT M.ID FROM MODOS_ENVIO M WHERE M.CODIGO = E.MODO);
UPDATE UNIDADES_MEDIDA U SET
  MAGNITUD_ID = (SELECT M.ID FROM MAGNITUDES M WHERE M.CODIGO = U.MAGNITUD);
UPDATE PERMISOS P SET
  MODULO_ID = (SELECT M.ID FROM MODULOS M WHERE M.CODIGO = P.MODULO),
  AMBITO_ID = (SELECT A.ID FROM AMBITOS A WHERE A.CODIGO = P.AMBITO);
UPDATE ROLES R SET
  AMBITO_ID = (SELECT A.ID FROM AMBITOS A WHERE A.CODIGO = R.AMBITO);
UPDATE USUARIOS U SET
  AMBITO_ID = (SELECT A.ID FROM AMBITOS A WHERE A.CODIGO = U.AMBITO);
UPDATE ROLES_PERMISOS R SET
  AMBITO_ID = (SELECT A.ID FROM AMBITOS A WHERE A.CODIGO = R.AMBITO);

INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD, MAGNITUD_ID)
  VALUES ('centímetro', 'cm', 'longitud', 3);
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD, MAGNITUD_ID)
  VALUES ('milímetro', 'mm', 'longitud', 3);
INSERT INTO UNIDADES_MEDIDA (NOMBRE, ABREVIATURA, MAGNITUD, MAGNITUD_ID)
  VALUES ('grado', 'grados', 'longitud', 7);

UPDATE SOLICITUD_MEDIDAS M SET
  TIPO_MEDIDA_ID = (SELECT T.ID FROM TIPOS_MEDIDA T
                     WHERE UPPER(T.NOMBRE) = UPPER(M.TIPO_MEDIDA)),
  UNIDAD_MEDIDA_ID = (SELECT U.ID FROM UNIDADES_MEDIDA U
                       WHERE U.ABREVIATURA = M.UNIDAD_MEDIDA);
UPDATE MAQUINAS Q SET
  UNIDAD_MEDIDA_ID = (SELECT U.ID FROM UNIDADES_MEDIDA U WHERE U.ABREVIATURA = 'h');
COMMIT;

