/* La llave de COTIZACIONES.CLIENTE_ID no tiene nombre propio. */
SET TERM ^ ;
EXECUTE BLOCK AS
  DECLARE VARIABLE V_NOMBRE VARCHAR(63);
BEGIN
  FOR SELECT TRIM(RC.RDB$CONSTRAINT_NAME)
        FROM RDB$RELATION_CONSTRAINTS RC
        JOIN RDB$INDEX_SEGMENTS S ON S.RDB$INDEX_NAME = RC.RDB$INDEX_NAME
       WHERE RC.RDB$RELATION_NAME = 'COTIZACIONES'
         AND RC.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY'
         AND S.RDB$FIELD_NAME = 'CLIENTE_ID'
        INTO :V_NOMBRE
  DO
    EXECUTE STATEMENT 'ALTER TABLE COTIZACIONES DROP CONSTRAINT ' || :V_NOMBRE;
END ^
SET TERM ; ^
COMMIT;

/* Los disparadores que leian columnas viejas, ya con las nuevas. */
SET TERM ^ ;

CREATE OR ALTER TRIGGER TR_COTIZACIONES_ESTADOS FOR COTIZACIONES
ACTIVE AFTER INSERT OR UPDATE POSITION 5
AS
BEGIN
  IF (UPDATING AND NEW.ESTADO_ID = OLD.ESTADO_ID) THEN
    EXIT;
  UPDATE COTIZACION_ESTADOS SET ACTIVO = FALSE
   WHERE COTIZACION_ID = NEW.ID AND ACTIVO = TRUE;
  INSERT INTO COTIZACION_ESTADOS (COTIZACION_ID, ESTADO_ID, FECHA, USUARIO_ID,
    MOTIVO, ACTIVO)
  VALUES (NEW.ID, NEW.ESTADO_ID, CURRENT_TIMESTAMP,
    CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER),
    IIF(NEW.ESTADO_ID = 3, NEW.MOTIVO_RECHAZO, NULL), TRUE);
END ^

CREATE OR ALTER TRIGGER TR_COTIZACIONES_AUD FOR COTIZACIONES
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_ACCION  VARCHAR(50);
  DECLARE VARIABLE V_ID      INTEGER;
  DECLARE VARIABLE V_DETALLE VARCHAR(500);
  DECLARE VARIABLE V_DET     VARCHAR(500);
  DECLARE VARIABLE V_ANTES   VARCHAR(20);
  DECLARE VARIABLE V_AHORA   VARCHAR(20);
BEGIN
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  V_DETALLE = RDB$GET_CONTEXT('USER_SESSION', 'DETALLE');
  IF (NOT DELETING) THEN
    SELECT CODIGO FROM ESTADOS_COTIZACION WHERE ID = NEW.ESTADO_ID INTO :V_AHORA;
  IF (NOT INSERTING) THEN
    SELECT CODIGO FROM ESTADOS_COTIZACION WHERE ID = OLD.ESTADO_ID INTO :V_ANTES;
  IF (INSERTING) THEN
  BEGIN
    V_ACCION = 'insertar';
    V_ID = NEW.ID;
    V_DET = 'estado ' || V_AHORA;
  END
  ELSE IF (UPDATING) THEN
  BEGIN
    V_ACCION = 'actualizar';
    V_ID = NEW.ID;
    V_DET = 'estado ' || V_ANTES || ' -> ' || V_AHORA;
  END
  ELSE
  BEGIN
    V_ACCION = 'borrar';
    V_ID = OLD.ID;
    V_DET = 'estado ' || V_ANTES;
  END
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'COTIZACIONES', :V_ID,
          COALESCE(:V_DETALLE, :V_DET));
END ^

CREATE OR ALTER TRIGGER TR_USUARIOS_DISPOSITIVOS_AUD FOR USUARIOS_DISPOSITIVOS
ACTIVE AFTER INSERT OR UPDATE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_MOTIVO  VARCHAR(20);
BEGIN
  IF (UPDATING AND OLD.ACTIVO IS NOT DISTINCT FROM NEW.ACTIVO) THEN EXIT;
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  IF (INSERTING) THEN
    INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
    VALUES (:V_USUARIO, 'insertar', 'USUARIOS_DISPOSITIVOS', NEW.ID,
            'registro del dispositivo ' || COALESCE(NEW.NOMBRE, NEW.UUID_DISPOSITIVO));
  ELSE
  BEGIN
    SELECT CODIGO FROM MOTIVOS_CIERRE WHERE ID = NEW.MOTIVO_CIERRE_ID
      INTO :V_MOTIVO;
    INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
    VALUES (:V_USUARIO, IIF(NEW.ACTIVO, 'reactivar', 'inactivar'), 'USUARIOS_DISPOSITIVOS', NEW.ID,
            'motivo: ' || COALESCE(:V_MOTIVO, '-'));
  END
END ^

CREATE OR ALTER TRIGGER TR_USUARIOS_PERMISOS_AUD FOR USUARIOS_PERMISOS
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 10
AS
  DECLARE VARIABLE V_USUARIO INTEGER;
  DECLARE VARIABLE V_ACCION  VARCHAR(50);
  DECLARE VARIABLE V_ID      INTEGER;
  DECLARE VARIABLE V_PERMISO INTEGER;
  DECLARE VARIABLE V_TIPO_ID INTEGER;
  DECLARE VARIABLE V_TIPO    VARCHAR(20);
  DECLARE VARIABLE V_DETALLE VARCHAR(500);
BEGIN
  V_USUARIO = CAST(RDB$GET_CONTEXT('USER_SESSION', 'USUARIO_ID') AS INTEGER);
  IF (V_USUARIO IS NULL) THEN EXCEPTION E_AUDITORIA_SIN_USUARIO;
  V_DETALLE = RDB$GET_CONTEXT('USER_SESSION', 'DETALLE');
  IF (INSERTING) THEN BEGIN V_ACCION = 'insertar';   V_ID = NEW.USUARIO_ID; V_PERMISO = NEW.PERMISO_ID; V_TIPO_ID = NEW.TIPO_EXCEPCION_ID; END
  ELSE IF (UPDATING) THEN BEGIN V_ACCION = 'actualizar'; V_ID = NEW.USUARIO_ID; V_PERMISO = NEW.PERMISO_ID; V_TIPO_ID = NEW.TIPO_EXCEPCION_ID; END
  ELSE BEGIN V_ACCION = 'borrar'; V_ID = OLD.USUARIO_ID; V_PERMISO = OLD.PERMISO_ID; V_TIPO_ID = OLD.TIPO_EXCEPCION_ID; END
  SELECT CODIGO FROM TIPOS_EXCEPCION WHERE ID = :V_TIPO_ID INTO :V_TIPO;
  INSERT INTO AUDITORIA (USUARIO_ID, ACCION, ENTIDAD, ENTIDAD_ID, DETALLE)
  VALUES (:V_USUARIO, :V_ACCION, 'USUARIOS_PERMISOS', :V_ID,
          COALESCE(:V_DETALLE, :V_TIPO || ' permiso ' || :V_PERMISO));
END ^

SET TERM ; ^
COMMIT;

