  FOREIGN KEY (MODO_ENVIO_ID) REFERENCES MODOS_ENVIO (ID);
ALTER TABLE UNIDADES_MEDIDA ADD CONSTRAINT FK_UNIDADES_MEDIDA_MAGNITUD
  FOREIGN KEY (MAGNITUD_ID) REFERENCES MAGNITUDES (ID);
ALTER TABLE PERMISOS ADD CONSTRAINT FK_PERMISOS_MODULO
  FOREIGN KEY (MODULO_ID) REFERENCES MODULOS (ID);
ALTER TABLE PERMISOS ADD CONSTRAINT FK_PERMISOS_AMBITO
  FOREIGN KEY (AMBITO_ID) REFERENCES AMBITOS (ID);
ALTER TABLE ROLES ADD CONSTRAINT FK_ROLES_AMBITO
  FOREIGN KEY (AMBITO_ID) REFERENCES AMBITOS (ID);
ALTER TABLE USUARIOS ADD CONSTRAINT FK_USUARIOS_AMBITO
  FOREIGN KEY (AMBITO_ID) REFERENCES AMBITOS (ID);
ALTER TABLE AUDITORIA ADD CONSTRAINT FK_AUDITORIA_USUARIO
  FOREIGN KEY (USUARIO_ID) REFERENCES USUARIOS (ID);
COMMIT;

ALTER TABLE PERMISOS ADD CONSTRAINT UQ_PERMISOS_ID_AMBITO UNIQUE (ID, AMBITO_ID);
ALTER TABLE ROLES ADD CONSTRAINT UQ_ROLES_ID_AMBITO UNIQUE (ID, AMBITO_ID);
ALTER TABLE USUARIOS ADD CONSTRAINT UQ_USUARIOS_ID_AMBITO UNIQUE (ID, AMBITO_ID);
COMMIT;

ALTER TABLE USUARIOS ADD CONSTRAINT FK_USUARIOS_ROL_AMBITO
  FOREIGN KEY (ROL_ID, AMBITO_ID) REFERENCES ROLES (ID, AMBITO_ID);
ALTER TABLE ROLES_PERMISOS ADD CONSTRAINT FK_ROLPERM_ROL
  FOREIGN KEY (ROL_ID, AMBITO_ID) REFERENCES ROLES (ID, AMBITO_ID);
ALTER TABLE ROLES_PERMISOS ADD CONSTRAINT FK_ROLPERM_PERMISO
  FOREIGN KEY (PERMISO_ID, AMBITO_ID) REFERENCES PERMISOS (ID, AMBITO_ID);
ALTER TABLE USUARIOS_PERMISOS ADD CONSTRAINT FK_USUPERM_USUARIO
  FOREIGN KEY (USUARIO_ID, AMBITO_ID) REFERENCES USUARIOS (ID, AMBITO_ID);
ALTER TABLE USUARIOS_PERMISOS ADD CONSTRAINT FK_USUPERM_PERMISO
  FOREIGN KEY (PERMISO_ID, AMBITO_ID) REFERENCES PERMISOS (ID, AMBITO_ID);

ALTER TABLE COTIZACIONES ADD CONSTRAINT CK_COTIZ_MOTIVO_DEVUELTA
  CHECK (ESTADO_ID <> 3 OR MOTIVO_RECHAZO IS NOT NULL);
ALTER TABLE COTIZACIONES ADD CONSTRAINT CK_COTIZ_PLAZO_ENTREGA
  CHECK ((PLAZO_ENTREGA_CANTIDAD IS NULL AND PLAZO_ENTREGA_UNIDAD_ID IS NULL) OR
         (PLAZO_ENTREGA_CANTIDAD > 0 AND PLAZO_ENTREGA_UNIDAD_ID IS NOT NULL));
ALTER TABLE COTIZACIONES ADD CONSTRAINT CK_COTIZ_GARANTIA
  CHECK ((GARANTIA_CANTIDAD IS NULL AND GARANTIA_UNIDAD_ID IS NULL) OR
         (GARANTIA_CANTIDAD > 0 AND GARANTIA_UNIDAD_ID IS NOT NULL));
ALTER TABLE EMPRESA ADD CONSTRAINT CK_EMPRESA_PLAZO_ENTREGA
  CHECK ((PLAZO_ENTREGA_CANTIDAD IS NULL AND PLAZO_ENTREGA_UNIDAD_ID IS NULL) OR
         (PLAZO_ENTREGA_CANTIDAD > 0 AND PLAZO_ENTREGA_UNIDAD_ID IS NOT NULL));
ALTER TABLE EMPRESA ADD CONSTRAINT CK_EMPRESA_GARANTIA
  CHECK ((GARANTIA_CANTIDAD IS NULL AND GARANTIA_UNIDAD_ID IS NULL) OR
         (GARANTIA_CANTIDAD > 0 AND GARANTIA_UNIDAD_ID IS NOT NULL));
ALTER TABLE COTIZACION_DETALLE ADD CONSTRAINT CK_DETALLE_TIPO CHECK (
    (TIPO_LINEA_ID = 1 AND MATERIAL_ID  IS NOT NULL AND MANO_OBRA_ID IS NULL AND MAQUINA_ID IS NULL) OR
    (TIPO_LINEA_ID = 2 AND MANO_OBRA_ID IS NOT NULL AND MATERIAL_ID  IS NULL AND MAQUINA_ID IS NULL) OR
    (TIPO_LINEA_ID = 3 AND MAQUINA_ID   IS NOT NULL AND MATERIAL_ID  IS NULL AND MANO_OBRA_ID IS NULL) OR
    (TIPO_LINEA_ID = 4 AND MATERIAL_ID  IS NULL AND MANO_OBRA_ID IS NULL AND MAQUINA_ID IS NULL));
ALTER TABLE PRECIOS_PROGRAMADOS ADD CONSTRAINT CK_PRECIOPROG_PRECIO CHECK (
    (MATERIAL_PRECIO_ID IS NULL OR MATERIAL_ID IS NOT NULL) AND
    (MANO_OBRA_PRECIO_ID IS NULL OR MANO_OBRA_ID IS NOT NULL) AND
    (MAQUINA_PRECIO_ID IS NULL OR MAQUINA_ID IS NOT NULL));
ALTER TABLE PRECIOS_PROGRAMADOS ADD CONSTRAINT CK_PRECIOPROG_APLICADO CHECK (
    ESTADO_ID <> 2 OR COALESCE(MATERIAL_PRECIO_ID, MANO_OBRA_PRECIO_ID,
                               MAQUINA_PRECIO_ID) IS NOT NULL);

CREATE INDEX IDX_COTIZ_ESTADOS_FECHA ON COTIZACION_ESTADOS (ESTADO_ID, FECHA);
CREATE INDEX IDX_PRECIOPROG_PENDIENTE ON PRECIOS_PROGRAMADOS (ESTADO_ID, FECHA_VIGENCIA);
COMMIT;

ALTER TRIGGER TR_CLIENTES_BU ACTIVE;
ALTER TRIGGER TR_CLIENTES_AUD ACTIVE;
ALTER TRIGGER TR_CLIENTE_CONTACTOS_BU ACTIVE;
ALTER TRIGGER TR_CLIENTE_CONTACTOS_AUD ACTIVE;
ALTER TRIGGER TR_CONSHIST_AUD ACTIVE;
ALTER TRIGGER TR_COTIZACIONES_BU ACTIVE;
ALTER TRIGGER TR_COTIZACIONES_AUD ACTIVE;
ALTER TRIGGER TR_COTIZACIONES_ESTADOS ACTIVE;
ALTER TRIGGER TR_COTIZACION_ENVIOS_AUD ACTIVE;
ALTER TRIGGER TR_EMPRESA_BU ACTIVE;
ALTER TRIGGER TR_EMPRESA_AUD ACTIVE;
ALTER TRIGGER TR_MAQUINAS_BU ACTIVE;
ALTER TRIGGER TR_MAQUINAS_AUD ACTIVE;
ALTER TRIGGER TR_PRECIOS_PROGRAMADOS_AUD ACTIVE;
ALTER TRIGGER TR_ROLES_PERMISOS_BU ACTIVE;
ALTER TRIGGER TR_ROLES_PERMISOS_AUD ACTIVE;
ALTER TRIGGER TR_SOLICITUDES_BU ACTIVE;
ALTER TRIGGER TR_SOLICITUDES_AUD ACTIVE;
ALTER TRIGGER TR_UNIDADES_MEDIDA_BU ACTIVE;
ALTER TRIGGER TR_UNIDADES_MEDIDA_AUD ACTIVE;
ALTER TRIGGER TR_USUARIOS_BU ACTIVE;
ALTER TRIGGER TR_USUARIOS_AUD ACTIVE;
ALTER TRIGGER TR_USUARIOS_DISPOSITIVOS_BU ACTIVE;
ALTER TRIGGER TR_USUARIOS_DISPOSITIVOS_AUD ACTIVE;
ALTER TRIGGER TR_USUARIOS_PERMISOS_BU ACTIVE;
ALTER TRIGGER TR_USUARIOS_PERMISOS_AUD ACTIVE;
COMMIT;

/* ---------------------------------------------------------------------------
   7. Vistas VT_: cada tabla con sus codigos resueltos. El backend lee de aqui
      y escribe en la tabla.
   --------------------------------------------------------------------------- */

CREATE VIEW VT_COTIZACIONES AS
SELECT K.*, E.CODIGO AS ESTADO, E.NOMBRE AS ESTADO_NOMBRE,
       S.CLIENTE_ID, F.NOMBRE AS FORMA_PAGO,
       UP.CODIGO AS PLAZO_ENTREGA_UNIDAD, UG.CODIGO AS GARANTIA_UNIDAD
  FROM COTIZACIONES K
  JOIN ESTADOS_COTIZACION E ON E.ID = K.ESTADO_ID
  JOIN SOLICITUDES S ON S.ID = K.SOLICITUD_ID
  LEFT JOIN FORMAS_PAGO F ON F.ID = K.FORMA_PAGO_ID
  LEFT JOIN UNIDADES_PLAZO UP ON UP.ID = K.PLAZO_ENTREGA_UNIDAD_ID
  LEFT JOIN UNIDADES_PLAZO UG ON UG.ID = K.GARANTIA_UNIDAD_ID;

CREATE VIEW VT_COTIZACION_ESTADOS AS
SELECT H.*, E.CODIGO AS ESTADO, E.NOMBRE AS ESTADO_NOMBRE
  FROM COTIZACION_ESTADOS H
  JOIN ESTADOS_COTIZACION E ON E.ID = H.ESTADO_ID;

CREATE VIEW VT_SOLICITUDES AS
SELECT S.*, E.CODIGO AS ESTADO, E.NOMBRE AS ESTADO_NOMBRE
  FROM SOLICITUDES S
  JOIN ESTADOS_SOLICITUD E ON E.ID = S.ESTADO_ID;

CREATE VIEW VT_CLIENTES AS
SELECT C.*, E.CODIGO AS CONSENTIMIENTO_ESTADO,
       C.TIPO_IDENTIFICACION_ID AS TIPO_IDENTIFICACION,
       T.NOMBRE AS TIPO_IDENTIFICACION_NOMBRE
  FROM CLIENTES C
  JOIN ESTADOS_CONSENTIMIENTO E ON E.ID = C.CONSENTIMIENTO_ESTADO_ID
  LEFT JOIN TIPOS_IDENTIFICACION T ON T.ID = C.TIPO_IDENTIFICACION_ID;

CREATE VIEW VT_CLIENTE_CONTACTOS AS
SELECT CC.*, E.CODIGO AS CONSENTIMIENTO_ESTADO
  FROM CLIENTE_CONTACTOS CC
  JOIN ESTADOS_CONSENTIMIENTO E ON E.ID = CC.CONSENTIMIENTO_ESTADO_ID;

CREATE VIEW VT_CONSENTIMIENTO_HISTORIAL AS
SELECT H.ID, H.CLIENTE_ID, H.CLIENTE_CONTACTO_ID, H.ACCION_ID, H.ORIGEN_ID,
       H.VERSION_TEXTO, H.FECHA, H.FIRMANTE_NOMBRE, H.FIRMANTE_IDENTIFICACION,
       H.FIRMA_MIME, A.CODIGO AS ACCION, O.CODIGO AS ORIGEN
  FROM CLIENTE_CONSENTIMIENTO_HISTORIAL H
  JOIN ACCIONES_CONSENTIMIENTO A ON A.ID = H.ACCION_ID
  LEFT JOIN ORIGENES_REGISTRO O ON O.ID = H.ORIGEN_ID;

CREATE VIEW VT_EMPRESA AS
SELECT X.*, UP.CODIGO AS PLAZO_ENTREGA_UNIDAD, UG.CODIGO AS GARANTIA_UNIDAD
  FROM EMPRESA X
  LEFT JOIN UNIDADES_PLAZO UP ON UP.ID = X.PLAZO_ENTREGA_UNIDAD_ID
  LEFT JOIN UNIDADES_PLAZO UG ON UG.ID = X.GARANTIA_UNIDAD_ID;

CREATE VIEW VT_SOLICITUD_MEDIDAS AS
SELECT M.*, T.NOMBRE AS TIPO_MEDIDA, U.ABREVIATURA AS UNIDAD_MEDIDA
  FROM SOLICITUD_MEDIDAS M
  JOIN TIPOS_MEDIDA T ON T.ID = M.TIPO_MEDIDA_ID
  JOIN UNIDADES_MEDIDA U ON U.ID = M.UNIDAD_MEDIDA_ID;

CREATE VIEW VT_SOLICITUD_ADJUNTOS AS
SELECT A.ID, A.UUID_LOCAL, A.TIPO_ADJUNTO_ID, A.NOMBRE_ARCHIVO, A.MIME,
       A.TAMANO_BYTES, A.ACTIVO, A.FECHA_CREACION, A.OBJVERSION, A.PIEZA_ID,
       A.HASH_SHA256, T.CODIGO AS TIPO
  FROM SOLICITUD_ADJUNTOS A
  JOIN TIPOS_ADJUNTO T ON T.ID = A.TIPO_ADJUNTO_ID;

CREATE VIEW VT_COTIZACION_DETALLE AS
SELECT D.*, T.CODIGO AS TIPO
  FROM COTIZACION_DETALLE D
  JOIN TIPOS_LINEA T ON T.ID = D.TIPO_LINEA_ID;

CREATE VIEW VT_PRECIOS_PROGRAMADOS AS
SELECT P.*, E.CODIGO AS ESTADO
  FROM PRECIOS_PROGRAMADOS P
  JOIN ESTADOS_PRECIO E ON E.ID = P.ESTADO_ID;

CREATE VIEW VT_UNIDADES_MEDIDA AS
SELECT U.*, M.CODIGO AS MAGNITUD
  FROM UNIDADES_MEDIDA U
  JOIN MAGNITUDES M ON M.ID = U.MAGNITUD_ID;

CREATE VIEW VT_MAQUINAS AS
SELECT Q.*, U.NOMBRE AS UNIDAD_MEDIDA
  FROM MAQUINAS Q
  JOIN UNIDADES_MEDIDA U ON U.ID = Q.UNIDAD_MEDIDA_ID;

CREATE VIEW VT_USUARIOS_DISPOSITIVOS AS
SELECT D.*, M.CODIGO AS MOTIVO
  FROM USUARIOS_DISPOSITIVOS D
  LEFT JOIN MOTIVOS_CIERRE M ON M.ID = D.MOTIVO_CIERRE_ID;

CREATE VIEW VT_USUARIOS_PERMISOS AS
SELECT P.*, T.CODIGO AS TIPO, A.CODIGO AS AMBITO
  FROM USUARIOS_PERMISOS P
  JOIN TIPOS_EXCEPCION T ON T.ID = P.TIPO_EXCEPCION_ID
  JOIN AMBITOS A ON A.ID = P.AMBITO_ID;

CREATE VIEW VT_ROLES_PERMISOS AS
SELECT RP.*, A.CODIGO AS AMBITO
  FROM ROLES_PERMISOS RP
  JOIN AMBITOS A ON A.ID = RP.AMBITO_ID;

CREATE VIEW VT_COTIZACION_ENVIOS AS
SELECT E.*, M.CODIGO AS MODO
  FROM COTIZACION_ENVIOS E
  JOIN MODOS_ENVIO M ON M.ID = E.MODO_ENVIO_ID;

CREATE VIEW VT_PERMISOS AS
SELECT P.*, M.CODIGO AS MODULO, A.CODIGO AS AMBITO
  FROM PERMISOS P
  JOIN MODULOS M ON M.ID = P.MODULO_ID
  JOIN AMBITOS A ON A.ID = P.AMBITO_ID;

CREATE VIEW VT_ROLES AS
SELECT R.*, A.CODIGO AS AMBITO
  FROM ROLES R
  JOIN AMBITOS A ON A.ID = R.AMBITO_ID;

CREATE VIEW VT_USUARIOS AS
SELECT U.*, A.CODIGO AS AMBITO
  FROM USUARIOS U
  JOIN AMBITOS A ON A.ID = U.AMBITO_ID;

COMMIT;

/* ---------------------------------------------------------------------------
   8. Las vistas de siempre, leyendo de VT_. Mismas columnas que antes; el
      estado en revision ahora se llama 'en_revision'.
   --------------------------------------------------------------------------- */

CREATE VIEW V_SOLICITUDES (ID, ESTADO, DESCRIPCION, FECHA_CAPTURA, FECHA_RECEPCION, CLIENTE_ID, CLIENTE_NOMBRE, ASESOR_ID, ASESOR_NOMBRE, DIAS_ESPERA, TIENE_COTIZACION) AS
SELECT S.ID, S.ESTADO, S.DESCRIPCION, S.FECHA_CAPTURA,
       COALESCE(S.FECHA_RECEPCION, S.FECHA_CAPTURA) AS FECHA_RECEPCION,
       S.CLIENTE_ID, C.NOMBRE AS CLIENTE_NOMBRE,
       S.ASESOR_ID, A.NOMBRE AS ASESOR_NOMBRE,
       CAST(DATEDIFF(DAY FROM COALESCE(S.FECHA_RECEPCION, S.FECHA_CAPTURA)
                     TO CURRENT_TIMESTAMP) AS INTEGER) AS DIAS_ESPERA,
       CASE WHEN EXISTS (SELECT 1 FROM VT_COTIZACIONES X
                          WHERE X.SOLICITUD_ID = S.ID)
            THEN TRUE ELSE FALSE END AS TIENE_COTIZACION
  FROM VT_SOLICITUDES S
  JOIN CLIENTES C ON C.ID = S.CLIENTE_ID
  JOIN USUARIOS A ON A.ID = S.ASESOR_ID;

CREATE VIEW V_COTIZACIONES (ID, NUMERO, ESTADO, DESCRIPCION_TRABAJO, SUBTOTAL_MATERIALES, SUBTOTAL_MANO_OBRA, SUBTOTAL_MAQUINA, COSTO_TOTAL, PORCENTAJE_AJUSTE, MOTIVO_AJUSTE, PORCENTAJE_IVA, MONTO_IMPUESTO, MONTO_TOTAL, MOTIVO_RECHAZO, FECHA_ELABORACION, FECHA_APROBACION, FECHA_ENVIO, FECHA_MODIFICACION, SOLICITUD_ID, FECHA_RECEPCION, CLIENTE_ID, CLIENTE_NOMBRE, ASESOR_ID, ASESOR_NOMBRE, ELABORADA_POR, ELABORADA_POR_NOMBRE, APROBADA_POR, APROBADA_POR_NOMBRE, TIPO_TRABAJO_ID, TIPO_TRABAJO_NOMBRE, DEVUELTA, DIAS_EN_ESTADO, DIAS_RESPUESTA) AS
SELECT K.ID, K.NUMERO, K.ESTADO, K.DESCRIPCION_TRABAJO,
       K.SUBTOTAL_MATERIALES, K.SUBTOTAL_MANO_OBRA, K.SUBTOTAL_MAQUINA,
       K.COSTO_TOTAL, K.PORCENTAJE_AJUSTE, K.MOTIVO_AJUSTE, K.PORCENTAJE_IVA,
       K.MONTO_IMPUESTO, K.MONTO_TOTAL, K.MOTIVO_RECHAZO,
       K.FECHA_ELABORACION, K.FECHA_APROBACION, K.FECHA_ENVIO,
       K.FECHA_MODIFICACION,
       K.SOLICITUD_ID,
       COALESCE(S.FECHA_RECEPCION, S.FECHA_CAPTURA) AS FECHA_RECEPCION,
       K.CLIENTE_ID, C.NOMBRE AS CLIENTE_NOMBRE,
       S.ASESOR_ID, A.NOMBRE AS ASESOR_NOMBRE,
       K.ELABORADA_POR, E.NOMBRE AS ELABORADA_POR_NOMBRE,
       K.APROBADA_POR, P.NOMBRE AS APROBADA_POR_NOMBRE,
       K.TIPO_TRABAJO_ID, T.NOMBRE AS TIPO_TRABAJO_NOMBRE,
       CASE WHEN K.ESTADO = 'devuelta' THEN TRUE ELSE FALSE END AS DEVUELTA,
       CAST(DATEDIFF(DAY FROM COALESCE(
              (SELECT MAX(H.FECHA) FROM VT_COTIZACION_ESTADOS H
                WHERE H.COTIZACION_ID = K.ID AND H.ACTIVO),
              K.FECHA_MODIFICACION) TO CURRENT_TIMESTAMP) AS INTEGER)
            AS DIAS_EN_ESTADO,
       CASE WHEN K.FECHA_ENVIO IS NOT NULL
            THEN CAST(DATEDIFF(DAY FROM COALESCE(S.FECHA_RECEPCION,
                      S.FECHA_CAPTURA) TO K.FECHA_ENVIO) AS INTEGER)
       END AS DIAS_RESPUESTA
  FROM VT_COTIZACIONES K
  JOIN VT_SOLICITUDES S ON S.ID = K.SOLICITUD_ID
  JOIN CLIENTES C ON C.ID = K.CLIENTE_ID
  JOIN USUARIOS A ON A.ID = S.ASESOR_ID
  JOIN USUARIOS E ON E.ID = K.ELABORADA_POR
  LEFT JOIN USUARIOS P ON P.ID = K.APROBADA_POR
  LEFT JOIN TIPOS_TRABAJO T ON T.ID = K.TIPO_TRABAJO_ID;

CREATE VIEW V_CATALOGO_ITEMS (TIPO, ID, CODIGO, NOMBRE, DESCRIPCION, UNIDAD_MEDIDA_ID, UNIDAD_MEDIDA, CATEGORIA_ID, CATEGORIA_NOMBRE, COSTO_UNITARIO, PRECIO_UNITARIO, COSTO_HORA, COSTO, FECHA_VIGENCIA, ACTIVO, PROGRAMADO_FECHA) AS
SELECT CAST('material' AS VARCHAR(10)) AS TIPO,
       M.ID, M.CODIGO, M.NOMBRE, M.DESCRIPCION,
       M.UNIDAD_MEDIDA_ID, U.NOMBRE AS UNIDAD_MEDIDA,
       CAST(NULL AS INTEGER) AS CATEGORIA_ID,
       CAST(NULL AS VARCHAR(120)) AS CATEGORIA_NOMBRE,
       P.COSTO_UNITARIO, P.PRECIO_UNITARIO,
       CAST(NULL AS NUMERIC(15,2)) AS COSTO_HORA,
       P.COSTO_UNITARIO AS COSTO, P.FECHA_VIGENCIA, M.ACTIVO,
       (SELECT MIN(PP.FECHA_VIGENCIA) FROM VT_PRECIOS_PROGRAMADOS PP
         WHERE PP.MATERIAL_ID = M.ID AND PP.ESTADO = 'pendiente')
         AS PROGRAMADO_FECHA
  FROM MATERIALES M
  JOIN UNIDADES_MEDIDA U ON U.ID = M.UNIDAD_MEDIDA_ID
  LEFT JOIN MATERIALES_PRECIOS P
    ON P.MATERIAL_ID = M.ID AND P.ACTIVO = TRUE
UNION ALL
SELECT CAST('mano_obra' AS VARCHAR(10)),
       MO.ID, MO.CODIGO, MO.NOMBRE, MO.DESCRIPCION,
       MO.UNIDAD_MEDIDA_ID, U.NOMBRE,
       MO.CATEGORIA_ID, CAT.NOMBRE,
       P.COSTO_UNITARIO, CAST(NULL AS NUMERIC(15,2)),
       CAST(NULL AS NUMERIC(15,2)),
       P.COSTO_UNITARIO, P.FECHA_VIGENCIA, MO.ACTIVO,
       (SELECT MIN(PP.FECHA_VIGENCIA) FROM VT_PRECIOS_PROGRAMADOS PP
         WHERE PP.MANO_OBRA_ID = MO.ID AND PP.ESTADO = 'pendiente')
  FROM MANO_OBRA MO
  JOIN MANO_OBRA_CATEGORIA CAT ON CAT.ID = MO.CATEGORIA_ID
  JOIN UNIDADES_MEDIDA U ON U.ID = MO.UNIDAD_MEDIDA_ID
  LEFT JOIN MANO_OBRA_PRECIOS P
    ON P.MANO_OBRA_ID = MO.ID AND P.ACTIVO = TRUE
UNION ALL
SELECT CAST('maquina' AS VARCHAR(10)),
       Q.ID, Q.CODIGO, Q.NOMBRE, Q.DESCRIPCION,
       Q.UNIDAD_MEDIDA_ID, U.NOMBRE,
       CAST(NULL AS INTEGER), CAST(NULL AS VARCHAR(120)),
       CAST(NULL AS NUMERIC(15,2)), CAST(NULL AS NUMERIC(15,2)),
       P.COSTO_HORA,
       P.COSTO_HORA, P.FECHA_VIGENCIA, Q.ACTIVO,
       (SELECT MIN(PP.FECHA_VIGENCIA) FROM VT_PRECIOS_PROGRAMADOS PP
         WHERE PP.MAQUINA_ID = Q.ID AND PP.ESTADO = 'pendiente')
  FROM MAQUINAS Q
  JOIN UNIDADES_MEDIDA U ON U.ID = Q.UNIDAD_MEDIDA_ID
  LEFT JOIN MAQUINAS_PRECIOS P
    ON P.MAQUINA_ID = Q.ID AND P.ACTIVO = TRUE;

CREATE VIEW V_TRABAJO_USUARIO (USUARIO_ID, POR_COTIZAR, MIS_BORRADORES, EN_APROBACION, POR_ENVIAR, POR_APROBAR, DIAS_MAS_ANTIGUA, MONTO_POR_APROBAR) AS
SELECT U.ID AS USUARIO_ID,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM V_SOLICITUDES S
         WHERE S.ESTADO = 'recibida' AND S.TIENE_COTIZACION = FALSE)
         AS POR_COTIZAR,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO IN ('borrador', 'devuelta'))
         AS MIS_BORRADORES,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO = 'en_revision')
         AS EN_APROBACION,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO = 'visto_bueno')
         AS POR_ENVIAR,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_COTIZACIONES C
         WHERE C.ESTADO = 'en_revision' AND C.ELABORADA_POR <> U.ID)
         AS POR_APROBAR,
       (SELECT CAST(COALESCE(MAX(C.DIAS_EN_ESTADO), 0) AS INTEGER)
          FROM V_COTIZACIONES C
         WHERE C.ESTADO = 'en_revision' AND C.ELABORADA_POR <> U.ID)
         AS DIAS_MAS_ANTIGUA,
       (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
          FROM VT_COTIZACIONES C
         WHERE C.ESTADO = 'en_revision' AND C.ELABORADA_POR <> U.ID)
         AS MONTO_POR_APROBAR
  FROM USUARIOS U;

CREATE VIEW V_RESUMEN_MES (DESDE, HASTA, COTIZADO_MES, APROBADAS_MES, MONTO_APROBADO_MES, RECHAZADAS_MES, RESPUESTA_MEDIA, ASESORES_ACTIVOS, TASA_APROBACION) AS
SELECT R.*,
       CAST(COALESCE(R.APROBADAS_MES * 100.0000
            / NULLIF(R.APROBADAS_MES + R.RECHAZADAS_MES, 0), 0) AS NUMERIC(5,2))
         AS TASA_APROBACION
  FROM (SELECT P.MES_DESDE AS DESDE, P.MES_HASTA AS HASTA,
       (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
          FROM VT_COTIZACION_ESTADOS H JOIN VT_COTIZACIONES C ON C.ID = H.COTIZACION_ID
         WHERE H.ESTADO = 'enviada'
           AND H.FECHA >= P.MES_DESDE AND H.FECHA < P.MES_HASTA)
         AS COTIZADO_MES,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_COTIZACION_ESTADOS H
         WHERE H.ESTADO = 'aprobada'
           AND H.FECHA >= P.MES_DESDE AND H.FECHA < P.MES_HASTA)
         AS APROBADAS_MES,
       (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
          FROM VT_COTIZACION_ESTADOS H JOIN VT_COTIZACIONES C ON C.ID = H.COTIZACION_ID
         WHERE H.ESTADO = 'aprobada'
           AND H.FECHA >= P.MES_DESDE AND H.FECHA < P.MES_HASTA)
         AS MONTO_APROBADO_MES,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_COTIZACION_ESTADOS H
         WHERE H.ESTADO = 'rechazada'
           AND H.FECHA >= P.MES_DESDE AND H.FECHA < P.MES_HASTA)
         AS RECHAZADAS_MES,
       (SELECT CAST(COALESCE(AVG(C.DIAS_RESPUESTA), 0) AS INTEGER)
          FROM VT_COTIZACION_ESTADOS H JOIN V_COTIZACIONES C ON C.ID = H.COTIZACION_ID
         WHERE H.ESTADO = 'enviada'
           AND H.FECHA >= P.MES_DESDE AND H.FECHA < P.MES_HASTA)
         AS RESPUESTA_MEDIA,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
          JOIN ROLES R ON R.ID = U.ROL_ID
         WHERE R.CODIGO = 'asesor' AND U.ACTIVO)
         AS ASESORES_ACTIVOS
  FROM V_PERIODO_ACTUAL P) R;

CREATE VIEW V_ASESORES_MES (ASESOR_ID, ASESOR_NOMBRE, ACTIVO, SOLICITUDES_MES, ESPERANDO_COTIZACION, APROBADAS_MES, MONTO_APROBADO_MES) AS
SELECT U.ID AS ASESOR_ID, U.NOMBRE AS ASESOR_NOMBRE, U.ACTIVO,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_SOLICITUDES S
         WHERE S.ASESOR_ID = U.ID
           AND S.FECHA_CAPTURA >= P.MES_DESDE
           AND S.FECHA_CAPTURA < P.MES_HASTA)
         AS SOLICITUDES_MES,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_SOLICITUDES S
         WHERE S.ASESOR_ID = U.ID
           AND S.ESTADO IN ('recibida', 'en_cotizacion')
           AND NOT EXISTS (SELECT 1 FROM VT_COTIZACIONES X
                            WHERE X.SOLICITUD_ID = S.ID
                              AND X.ESTADO IN ('enviada', 'aprobada', 'rechazada')))
         AS ESPERANDO_COTIZACION,
       (SELECT CAST(COUNT(*) AS INTEGER)
          FROM VT_COTIZACION_ESTADOS H JOIN V_COTIZACIONES C ON C.ID = H.COTIZACION_ID
         WHERE C.ASESOR_ID = U.ID AND H.ESTADO = 'aprobada'
           AND H.FECHA >= P.MES_DESDE AND H.FECHA < P.MES_HASTA)
         AS APROBADAS_MES,
       (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
          FROM VT_COTIZACION_ESTADOS H JOIN V_COTIZACIONES C ON C.ID = H.COTIZACION_ID
         WHERE C.ASESOR_ID = U.ID AND H.ESTADO = 'aprobada'
           AND H.FECHA >= P.MES_DESDE AND H.FECHA < P.MES_HASTA)
         AS MONTO_APROBADO_MES
  FROM USUARIOS U
  JOIN ROLES R ON R.ID = U.ROL_ID
  CROSS JOIN V_PERIODO_ACTUAL P
 WHERE R.CODIGO = 'asesor';

CREATE VIEW V_COTIZACIONES_POR_ESTADO (ESTADO, ORDEN, CANTIDAD, MONTO) AS
SELECT E.CODIGO AS ESTADO, CAST(E.ORDEN AS INTEGER) AS ORDEN,
       CAST(COUNT(*) AS INTEGER) AS CANTIDAD,
       CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2)) AS MONTO
  FROM COTIZACIONES C
  JOIN ESTADOS_COTIZACION E ON E.ID = C.ESTADO_ID
 GROUP BY E.CODIGO, E.ORDEN;

CREATE VIEW V_SEGUIMIENTO_ASESOR (ID, ASESOR_ID, FECHA_CAPTURA, CLIENTE_NOMBRE, DESCRIPCION, ESTADO, COTIZACION_ID, MONTO_APROBADO, UUID_LOCAL, NOMBRE_PROYECTO, COTIZACION_NUMERO, FECHA_CAMBIO) AS
SELECT S.ID, S.ASESOR_ID, S.FECHA_CAPTURA, S.CLIENTE_NOMBRE, S.DESCRIPCION,
       COALESCE(K.ESTADO, S.ESTADO) AS ESTADO,
       K.ID AS COTIZACION_ID, K.MONTO_TOTAL AS MONTO_APROBADO,
       T.UUID_LOCAL, T.NOMBRE_PROYECTO, K.NUMERO AS COTIZACION_NUMERO,
       MAXVALUE(T.FECHA_MODIFICACION,
                COALESCE(K.FECHA_MODIFICACION, T.FECHA_MODIFICACION))
         AS FECHA_CAMBIO
  FROM V_SOLICITUDES S
  JOIN VT_SOLICITUDES T ON T.ID = S.ID
  LEFT JOIN VT_COTIZACIONES K ON K.ID =
       (SELECT MAX(X.ID) FROM VT_COTIZACIONES X WHERE X.SOLICITUD_ID = S.ID);

CREATE VIEW V_COTIZACIONES_DIA (FECHA, ANIO, MES, ESTADO, ASESOR_ID, ASESOR_NOMBRE, TIPO_TRABAJO_ID, TIPO_TRABAJO_NOMBRE, ELABORADA_POR, CANTIDAD, MONTO_TOTAL, APROBADAS, RECHAZADAS, MONTO_APROBADO, SUMA_DIAS_RESPUESTA, CON_RESPUESTA) AS
SELECT CAST(H.FECHA AS DATE) AS FECHA,
       CAST(EXTRACT(YEAR FROM H.FECHA) AS INTEGER) AS ANIO,
       CAST(EXTRACT(MONTH FROM H.FECHA) AS INTEGER) AS MES,
       H.ESTADO, K.ASESOR_ID, K.ASESOR_NOMBRE, K.TIPO_TRABAJO_ID,
       K.TIPO_TRABAJO_NOMBRE, K.ELABORADA_POR,
       CAST(COUNT(*) AS INTEGER) AS CANTIDAD,
       CAST(COALESCE(SUM(K.MONTO_TOTAL), 0) AS NUMERIC(18,2)) AS MONTO_TOTAL,
       CAST(SUM(CASE WHEN H.ESTADO = 'aprobada' THEN 1 ELSE 0 END)
            AS INTEGER) AS APROBADAS,
       CAST(SUM(CASE WHEN H.ESTADO = 'rechazada' THEN 1 ELSE 0 END)
            AS INTEGER) AS RECHAZADAS,
       CAST(COALESCE(SUM(CASE WHEN H.ESTADO = 'aprobada'
            THEN K.MONTO_TOTAL ELSE 0 END), 0) AS NUMERIC(18,2))
            AS MONTO_APROBADO,
       CAST(COALESCE(SUM(CASE WHEN H.ESTADO = 'enviada'
            THEN DATEDIFF(DAY FROM K.FECHA_RECEPCION TO H.FECHA) END), 0)
            AS INTEGER) AS SUMA_DIAS_RESPUESTA,
       CAST(COUNT(CASE WHEN H.ESTADO = 'enviada' THEN 1 END) AS INTEGER)
            AS CON_RESPUESTA
  FROM VT_COTIZACION_ESTADOS H
  JOIN V_COTIZACIONES K ON K.ID = H.COTIZACION_ID
 GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9;

CREATE VIEW V_CONSENTIMIENTOS (ID, CLIENTE_ID, CLIENTE_CONTACTO_ID, ACCION, VERSION_TEXTO, FECHA, FIRMANTE_NOMBRE, FIRMANTE_IDENTIFICACION, FIRMA_MIME, ORIGEN) AS
SELECT ID, CLIENTE_ID, CLIENTE_CONTACTO_ID, ACCION, VERSION_TEXTO, FECHA,
       FIRMANTE_NOMBRE, FIRMANTE_IDENTIFICACION, FIRMA_MIME, ORIGEN
  FROM VT_CONSENTIMIENTO_HISTORIAL;

CREATE VIEW V_USUARIOS (ID, CORREO, NOMBRE, ROL_ID, ROL, ROL_NOMBRE, AMBITO, ACTIVO, DEBE_CAMBIAR_CLAVE, FECHA_CREACION, FECHA_MODIFICACION, FECHA_CLAVE, EXCEPCIONES) AS
SELECT U.ID, U.CORREO, U.NOMBRE, U.ROL_ID, R.CODIGO AS ROL,
       R.NOMBRE AS ROL_NOMBRE, U.AMBITO, U.ACTIVO, U.DEBE_CAMBIAR_CLAVE,
       U.FECHA_CREACION, U.FECHA_MODIFICACION,
       (SELECT MAX(C.FECHA_CAMBIO) FROM USUARIOS_CLAVES C
         WHERE C.USUARIO_ID = U.ID AND C.ACTIVO = TRUE) AS FECHA_CLAVE,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_USUARIOS_PERMISOS P
         WHERE P.USUARIO_ID = U.ID AND P.ACTIVO = TRUE) AS EXCEPCIONES
  FROM VT_USUARIOS U
  JOIN ROLES R ON R.ID = U.ROL_ID;

CREATE VIEW V_ROLES (ID, CODIGO, NOMBRE, AMBITO, USUARIOS_ACTIVOS) AS
SELECT R.ID, R.CODIGO, R.NOMBRE, R.AMBITO,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM USUARIOS U
         WHERE U.ROL_ID = R.ID AND U.ACTIVO = TRUE) AS USUARIOS_ACTIVOS
  FROM VT_ROLES R;

CREATE VIEW V_USUARIOS_PERMISOS (USUARIO_ID, PERMISO_ID, PERMISO, NOMBRE, MODULO, TIPO, MOTIVO, FECHA_CREACION) AS
SELECT UP.USUARIO_ID, UP.PERMISO_ID, P.CODIGO AS PERMISO, P.NOMBRE,
       P.MODULO, UP.TIPO, UP.MOTIVO, UP.FECHA_CREACION
  FROM VT_USUARIOS_PERMISOS UP
  JOIN VT_PERMISOS P ON P.ID = UP.PERMISO_ID
 WHERE UP.ACTIVO = TRUE;

CREATE VIEW V_SOLICITUD_ADJUNTOS (ID, SOLICITUD_ID, PIEZA_ID, PIEZA_NOMBRE, UUID_LOCAL, TIPO, NOMBRE_ARCHIVO, MIME, TAMANO_BYTES, ACTIVO, FECHA_CREACION) AS
SELECT A.ID, P.SOLICITUD_ID, A.PIEZA_ID, P.NOMBRE AS PIEZA_NOMBRE, A.UUID_LOCAL,
       A.TIPO, A.NOMBRE_ARCHIVO, A.MIME, A.TAMANO_BYTES, A.ACTIVO, A.FECHA_CREACION
  FROM VT_SOLICITUD_ADJUNTOS A
  JOIN SOLICITUD_PIEZAS P ON P.ID = A.PIEZA_ID;

CREATE VIEW V_SOLICITUD_MEDIDAS (ID, SOLICITUD_ID, PIEZA_ID, PIEZA_NOMBRE, UUID_LOCAL, CROQUIS_ID, ETIQUETA, TIPO_MEDIDA, VALOR, UNIDAD_MEDIDA, CANTIDAD, OBSERVACION, ORDEN, FECHA_CREACION) AS
SELECT M.ID, P.SOLICITUD_ID, M.PIEZA_ID, P.NOMBRE AS PIEZA_NOMBRE, M.UUID_LOCAL,
       M.CROQUIS_ID, M.ETIQUETA,
       M.TIPO_MEDIDA, M.VALOR, M.UNIDAD_MEDIDA, M.CANTIDAD, M.OBSERVACION,
       M.ORDEN, M.FECHA_CREACION
  FROM VT_SOLICITUD_MEDIDAS M
  JOIN SOLICITUD_PIEZAS P ON P.ID = M.PIEZA_ID
 WHERE M.ACTIVO = TRUE;

CREATE VIEW V_SOLICITUD_PIEZAS (ID, SOLICITUD_ID, UUID_LOCAL, NOMBRE, ORDEN, TIPO_TRABAJO_ID, TIPO_TRABAJO_NOMBRE, TIPO_MATERIAL_ID, TIPO_MATERIAL_NOMBRE, ACABADO_ID, ACABADO_NOMBRE, MEDIDAS, FOTOS, CROQUIS, ACTIVO, FECHA_CREACION, FECHA_MODIFICACION) AS
SELECT P.ID, P.SOLICITUD_ID, P.UUID_LOCAL, P.NOMBRE, P.ORDEN,
       P.TIPO_TRABAJO_ID, T.NOMBRE AS TIPO_TRABAJO_NOMBRE,
       P.TIPO_MATERIAL_ID, M.NOMBRE AS TIPO_MATERIAL_NOMBRE,
       P.ACABADO_ID, A.NOMBRE AS ACABADO_NOMBRE,
       CAST((SELECT COUNT(*) FROM VT_SOLICITUD_MEDIDAS X WHERE X.PIEZA_ID = P.ID AND X.ACTIVO) AS INTEGER) AS MEDIDAS,
       CAST((SELECT COUNT(*) FROM VT_SOLICITUD_ADJUNTOS X
              WHERE X.PIEZA_ID = P.ID AND X.TIPO = 'foto' AND X.ACTIVO) AS INTEGER) AS FOTOS,
       CAST((SELECT COUNT(*) FROM VT_SOLICITUD_ADJUNTOS X
              WHERE X.PIEZA_ID = P.ID AND X.TIPO = 'croquis' AND X.ACTIVO) AS INTEGER) AS CROQUIS,
       P.ACTIVO, P.FECHA_CREACION, P.FECHA_MODIFICACION
  FROM SOLICITUD_PIEZAS P
  LEFT JOIN TIPOS_TRABAJO  T ON T.ID = P.TIPO_TRABAJO_ID
  LEFT JOIN TIPOS_MATERIAL M ON M.ID = P.TIPO_MATERIAL_ID
  LEFT JOIN ACABADOS       A ON A.ID = P.ACABADO_ID;

CREATE VIEW V_USUARIOS_DISPOSITIVOS (ID, USUARIO_ID, CORREO, USUARIO_NOMBRE, UUID_DISPOSITIVO, NOMBRE, FECHA_VENCE, FECHA_ULTIMO_USO, MOTIVO, ACTIVO, FECHA_CREACION, FECHA_MODIFICACION) AS
SELECT D.ID, D.USUARIO_ID, U.CORREO, U.NOMBRE AS USUARIO_NOMBRE,
       D.UUID_DISPOSITIVO, D.NOMBRE, D.FECHA_VENCE, D.FECHA_ULTIMO_USO,
       D.MOTIVO, D.ACTIVO, D.FECHA_CREACION, D.FECHA_MODIFICACION
  FROM VT_USUARIOS_DISPOSITIVOS D
  JOIN USUARIOS U ON U.ID = D.USUARIO_ID;

CREATE VIEW V_COTIZACION_HISTORIAL (ID, COTIZACION_ID, ESTADO, FECHA, USUARIO_ID, USUARIO_NOMBRE, MOTIVO, ACTIVO) AS
SELECT H.ID, H.COTIZACION_ID, H.ESTADO, H.FECHA, H.USUARIO_ID,
       COALESCE(U.NOMBRE, '') AS USUARIO_NOMBRE, H.MOTIVO, H.ACTIVO
  FROM VT_COTIZACION_ESTADOS H
  LEFT JOIN USUARIOS U ON U.ID = H.USUARIO_ID;

CREATE VIEW V_CLIENTES_RESPUESTA (ID, NUMERO, CLIENTE_ID, CLIENTE_NOMBRE, ASESOR_ID, ELABORADA_POR, ESTADO, FECHA_ENVIO, MONTO_TOTAL, DIAS_SIN_RESPUESTA) AS
SELECT K.ID, K.NUMERO, K.CLIENTE_ID, C.NOMBRE AS CLIENTE_NOMBRE,
       S.ASESOR_ID, K.ELABORADA_POR, K.ESTADO, K.FECHA_ENVIO, K.MONTO_TOTAL,
       E.DIAS_SIN_RESPUESTA
  FROM VT_COTIZACIONES K
  JOIN CLIENTES C ON C.ID = K.CLIENTE_ID
  JOIN VT_SOLICITUDES S ON S.ID = K.SOLICITUD_ID
  CROSS JOIN EMPRESA E
 WHERE K.FECHA_ENVIO IS NOT NULL;

CREATE VIEW V_DASH_ESTADO_ASESOR (ASESOR_ID, ESTADO, CON_COTIZACION, CANTIDAD, DIAS_MAS_ANTIGUA) AS
SELECT ASESOR_ID, ESTADO, (COTIZACION_ID IS NOT NULL) AS CON_COTIZACION,
       CAST(COUNT(*) AS INTEGER) AS CANTIDAD,
       CAST(COALESCE(MAX(DATEDIFF(DAY FROM CAST(FECHA_CAPTURA AS DATE)
         TO CURRENT_DATE)), 0) AS INTEGER) AS DIAS_MAS_ANTIGUA
  FROM V_SEGUIMIENTO_ASESOR
 GROUP BY 1, 2, 3;

CREATE VIEW V_DASH_SOLICITUDES_MES (ASESOR_ID, ANIO, MES, CANTIDAD) AS
SELECT ASESOR_ID,
       CAST(EXTRACT(YEAR FROM FECHA_CAPTURA) AS INTEGER) AS ANIO,
       CAST(EXTRACT(MONTH FROM FECHA_CAPTURA) AS INTEGER) AS MES,
       CAST(COUNT(*) AS INTEGER) AS CANTIDAD
  FROM V_SEGUIMIENTO_ASESOR
 GROUP BY 1, 2, 3;

CREATE VIEW V_DASH_ENVIADAS (COTIZACION_ID, NUMERO, CLIENTE_NOMBRE, ASESOR_ID, ELABORADA_POR, FECHA_ENVIO, DIAS_SIN_RESPUESTA, DIAS, NIVEL) AS
SELECT ID AS COTIZACION_ID, NUMERO, CLIENTE_NOMBRE, ASESOR_ID, ELABORADA_POR,
       FECHA_ENVIO, DIAS_SIN_RESPUESTA,
       CAST(DATEDIFF(DAY FROM CAST(FECHA_ENVIO AS DATE) TO CURRENT_DATE)
         AS INTEGER) AS DIAS,
       CAST(TRIM(CASE
         WHEN DATEDIFF(DAY FROM CAST(FECHA_ENVIO AS DATE) TO CURRENT_DATE)
              >= COALESCE(DIAS_SIN_RESPUESTA, 0) * 1.5 THEN 'alto'
         WHEN DATEDIFF(DAY FROM CAST(FECHA_ENVIO AS DATE) TO CURRENT_DATE)
              >= COALESCE(DIAS_SIN_RESPUESTA, 0) THEN 'medio'
         ELSE 'bajo' END) AS VARCHAR(5)) AS NIVEL
  FROM V_CLIENTES_RESPUESTA
 WHERE ESTADO = 'enviada';

CREATE VIEW V_DASH_EN_CURSO (COTIZACION_ID, NUMERO, CLIENTE_NOMBRE, ESTADO, ELABORADA_POR, ELABORADA_POR_NOMBRE, MOTIVO_RECHAZO, FECHA_MODIFICACION, DIAS, ESTANCADA, NIVEL) AS
SELECT ID AS COTIZACION_ID, NUMERO, CLIENTE_NOMBRE, ESTADO, ELABORADA_POR,
       ELABORADA_POR_NOMBRE, MOTIVO_RECHAZO, FECHA_MODIFICACION,
       CAST(COALESCE(DIAS_EN_ESTADO, 0) AS INTEGER) AS DIAS,
       (COALESCE(DIAS_EN_ESTADO, 0) >= 5) AS ESTANCADA,
       CAST(TRIM(CASE WHEN COALESCE(DIAS_EN_ESTADO, 0) >= 8 THEN 'alto'
                      WHEN COALESCE(DIAS_EN_ESTADO, 0) >= 5 THEN 'medio'
                      ELSE 'bajo' END) AS VARCHAR(5)) AS NIVEL
  FROM V_COTIZACIONES
 WHERE ESTADO IN ('borrador', 'en_revision', 'devuelta', 'visto_bueno');

CREATE VIEW V_DASH_ETAPAS (ELABORADA_POR, ESTADO, CANTIDAD) AS
SELECT ELABORADA_POR, ESTADO, CAST(COUNT(*) AS INTEGER) AS CANTIDAD
  FROM VT_COTIZACIONES
 WHERE ESTADO IN ('borrador', 'en_revision', 'devuelta', 'visto_bueno',
                  'enviada')
 GROUP BY 1, 2;

CREATE VIEW V_DASH_CARGA (ELABORADA_POR, ELABORADA_POR_NOMBRE, CANTIDAD) AS
SELECT ELABORADA_POR, ELABORADA_POR_NOMBRE, CAST(COUNT(*) AS INTEGER) AS CANTIDAD
  FROM V_DASH_EN_CURSO
 GROUP BY 1, 2;

CREATE VIEW V_DASH_PASOS_MES (ELABORADA_POR, ANIO, MES, PRESENTADAS, VISTO_BUENO, DEVUELTAS, APROBADAS, RECHAZADAS, MONTO_APROBADO) AS
SELECT ELABORADA_POR, ANIO, MES,
       CAST(SUM(CASE WHEN ESTADO = 'en_revision' THEN CANTIDAD ELSE 0 END)
            AS INTEGER) AS PRESENTADAS,
       CAST(SUM(CASE WHEN ESTADO = 'visto_bueno' THEN CANTIDAD ELSE 0 END)
            AS INTEGER) AS VISTO_BUENO,
       CAST(SUM(CASE WHEN ESTADO = 'devuelta' THEN CANTIDAD ELSE 0 END)
            AS INTEGER) AS DEVUELTAS,
       CAST(SUM(APROBADAS) AS INTEGER) AS APROBADAS,
       CAST(SUM(RECHAZADAS) AS INTEGER) AS RECHAZADAS,
       CAST(COALESCE(SUM(MONTO_APROBADO), 0) AS NUMERIC(18,2)) AS MONTO_APROBADO
  FROM V_COTIZACIONES_DIA
 GROUP BY 1, 2, 3;

CREATE VIEW V_DASH_PASOS_EQUIPO (ANIO, MES, PRESENTADAS, VISTO_BUENO, DEVUELTAS, APROBADAS, RECHAZADAS, MONTO_APROBADO) AS
SELECT ANIO, MES,
       CAST(SUM(PRESENTADAS) AS INTEGER) AS PRESENTADAS,
       CAST(SUM(VISTO_BUENO) AS INTEGER) AS VISTO_BUENO,
       CAST(SUM(DEVUELTAS) AS INTEGER) AS DEVUELTAS,
       CAST(SUM(APROBADAS) AS INTEGER) AS APROBADAS,
       CAST(SUM(RECHAZADAS) AS INTEGER) AS RECHAZADAS,
       CAST(COALESCE(SUM(MONTO_APROBADO), 0) AS NUMERIC(18,2)) AS MONTO_APROBADO
  FROM V_DASH_PASOS_MES
 GROUP BY 1, 2;

CREATE VIEW V_DASH_ASESOR_GRUPOS (ASESOR_ID, GRUPO, ORDEN, CANTIDAD, DIAS_MAS_ANTIGUA) AS
SELECT ASESOR_ID, GRUPO,
       CAST(CASE GRUPO WHEN 'esperando' THEN 1 WHEN 'elaboracion' THEN 2
                       WHEN 'enviada' THEN 3 WHEN 'aprobada' THEN 4
                       WHEN 'rechazada' THEN 5 ELSE 6 END AS INTEGER) AS ORDEN,
       CAST(SUM(CANTIDAD) AS INTEGER) AS CANTIDAD,
       CAST(MAX(DIAS_MAS_ANTIGUA) AS INTEGER) AS DIAS_MAS_ANTIGUA
  FROM (SELECT ASESOR_ID, CANTIDAD, DIAS_MAS_ANTIGUA,
               CAST(TRIM(CASE
                 WHEN ESTADO = 'descartada' AND CON_COTIZACION
                   THEN 'sin_respuesta'
                 WHEN ESTADO IN ('borrador', 'en_revision', 'devuelta',
                                 'visto_bueno') THEN 'elaboracion'
                 WHEN ESTADO = 'enviada' THEN 'enviada'
                 WHEN ESTADO = 'aprobada' THEN 'aprobada'
                 WHEN ESTADO IN ('rechazada', 'descartada') THEN 'rechazada'
                 ELSE 'esperando' END) AS VARCHAR(15)) AS GRUPO
          FROM V_DASH_ESTADO_ASESOR)
 GROUP BY ASESOR_ID, GRUPO;

CREATE VIEW V_DASH_ASESOR_RESUMEN (ASESOR_ID, DIAS_MAS_ANTIGUA, TASA_APROBACION, SOLICITUDES_MES_ANTERIOR, VARIACION_SOLICITUDES, MONTO_APROBADO_ANTERIOR, VARIACION_MONTO, MES_ANTERIOR) AS
SELECT R.ASESOR_ID, R.DIAS_MAS_ANTIGUA, R.TASA_APROBACION,
       R.SOLICITUDES_MES_ANTERIOR,
       CAST(R.SOLICITUDES_ACTUAL - R.SOLICITUDES_MES_ANTERIOR AS INTEGER)
         AS VARIACION_SOLICITUDES,
       R.MONTO_APROBADO_ANTERIOR,
       CASE WHEN R.MONTO_APROBADO_ANTERIOR > 0
            THEN CAST((R.MONTO_ACTUAL - R.MONTO_APROBADO_ANTERIOR) * 100.0000
                 / R.MONTO_APROBADO_ANTERIOR AS NUMERIC(7,2)) END
         AS VARIACION_MONTO,
       R.MES_ANTERIOR
  FROM (SELECT G.ASESOR_ID, P.MES_ANTERIOR,
               CAST(COALESCE(MAX(CASE WHEN G.GRUPO = 'esperando'
                    THEN G.DIAS_MAS_ANTIGUA END), 0) AS INTEGER)
                 AS DIAS_MAS_ANTIGUA,
               CAST(COALESCE(SUM(CASE WHEN G.GRUPO = 'aprobada'
                    THEN G.CANTIDAD END) * 100.0000
                    / NULLIF(SUM(CASE WHEN G.GRUPO IN ('aprobada',
                    'rechazada') THEN G.CANTIDAD END), 0), 0) AS NUMERIC(5,2))
                 AS TASA_APROBACION,
               (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_SOLICITUDES S
                 WHERE S.ASESOR_ID = G.ASESOR_ID
                   AND S.FECHA_CAPTURA >= P.MES_DESDE
                   AND S.FECHA_CAPTURA < P.MES_HASTA) AS SOLICITUDES_ACTUAL,
               (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_SOLICITUDES S
                 WHERE S.ASESOR_ID = G.ASESOR_ID
                   AND S.FECHA_CAPTURA >= P.MES_ANTERIOR
                   AND S.FECHA_CAPTURA < P.MES_DESDE)
                 AS SOLICITUDES_MES_ANTERIOR,
               (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
                  FROM VT_COTIZACION_ESTADOS H
                  JOIN V_COTIZACIONES C ON C.ID = H.COTIZACION_ID
                 WHERE C.ASESOR_ID = G.ASESOR_ID AND H.ESTADO = 'aprobada'
                   AND H.FECHA >= P.MES_DESDE AND H.FECHA < P.MES_HASTA)
                 AS MONTO_ACTUAL,
               (SELECT CAST(COALESCE(SUM(C.MONTO_TOTAL), 0) AS NUMERIC(18,2))
                  FROM VT_COTIZACION_ESTADOS H
                  JOIN V_COTIZACIONES C ON C.ID = H.COTIZACION_ID
                 WHERE C.ASESOR_ID = G.ASESOR_ID AND H.ESTADO = 'aprobada'
                   AND H.FECHA >= P.MES_ANTERIOR AND H.FECHA < P.MES_DESDE)
                 AS MONTO_APROBADO_ANTERIOR
          FROM V_DASH_ASESOR_GRUPOS G
         CROSS JOIN V_PERIODO_ACTUAL P
         GROUP BY G.ASESOR_ID, P.MES_DESDE, P.MES_HASTA, P.MES_ANTERIOR) R;

CREATE VIEW V_DASH_ETAPAS_USUARIO (USUARIO_ID, ESTADO, ORDEN, CANTIDAD) AS
SELECT U.ID AS USUARIO_ID, E.ESTADO, E.ORDEN,
       CAST(COALESCE(D.CANTIDAD, 0) AS INTEGER) AS CANTIDAD
  FROM USUARIOS U
 CROSS JOIN (SELECT CAST(CODIGO AS VARCHAR(15)) AS ESTADO,
                    CAST(ORDEN AS INTEGER) AS ORDEN
               FROM ESTADOS_COTIZACION
              WHERE CODIGO IN ('borrador', 'en_revision', 'devuelta',
                               'visto_bueno', 'enviada')) E
  LEFT JOIN V_DASH_ETAPAS D ON D.ELABORADA_POR = U.ID AND D.ESTADO = E.ESTADO
UNION ALL
SELECT U.ID, CAST('aprobada' AS VARCHAR(15)), 6,
       CAST(COALESCE(P.APROBADAS, 0) AS INTEGER)
  FROM USUARIOS U
  LEFT JOIN V_DASH_PASOS_MES P
    ON P.ELABORADA_POR = U.ID
   AND P.ANIO = EXTRACT(YEAR FROM CURRENT_DATE)
   AND P.MES = EXTRACT(MONTH FROM CURRENT_DATE);

CREATE VIEW V_DASH_ASISTENTE_RESUMEN (USUARIO_ID, DIAS_MAS_ANTIGUA, DEVUELTAS, SIN_RESPUESTA, PRESENTADAS_MES, APROBADAS_MES, RECHAZADAS_MES, MONTO_APROBADO_MES, TASA_MES, DIAS_PLAZO) AS
SELECT U.ID AS USUARIO_ID,
       (SELECT CAST(COALESCE(MAX(S.DIAS_ESPERA), 0) AS INTEGER)
          FROM V_SOLICITUDES S
         WHERE S.ESTADO = 'recibida' AND S.TIENE_COTIZACION = FALSE)
         AS DIAS_MAS_ANTIGUA,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM VT_COTIZACIONES C
         WHERE C.ELABORADA_POR = U.ID AND C.ESTADO = 'devuelta')
         AS DEVUELTAS,
       (SELECT CAST(COUNT(*) AS INTEGER) FROM V_DASH_ENVIADAS V
         WHERE V.ELABORADA_POR = U.ID
           AND V.DIAS > COALESCE(V.DIAS_SIN_RESPUESTA, 0))
         AS SIN_RESPUESTA,
       CAST(COALESCE(P.PRESENTADAS, 0) AS INTEGER) AS PRESENTADAS_MES,
       CAST(COALESCE(P.APROBADAS, 0) AS INTEGER) AS APROBADAS_MES,
       CAST(COALESCE(P.RECHAZADAS, 0) AS INTEGER) AS RECHAZADAS_MES,
       CAST(COALESCE(P.MONTO_APROBADO, 0) AS NUMERIC(18,2))
         AS MONTO_APROBADO_MES,
       CAST(COALESCE(P.APROBADAS * 100.0000
            / NULLIF(P.APROBADAS + P.RECHAZADAS, 0), 0) AS NUMERIC(5,2))
         AS TASA_MES,
       (SELECT CAST(COALESCE(MAX(E.DIAS_SIN_RESPUESTA), 7) AS INTEGER)
          FROM EMPRESA E) AS DIAS_PLAZO
  FROM USUARIOS U
  LEFT JOIN V_DASH_PASOS_MES P
    ON P.ELABORADA_POR = U.ID
   AND P.ANIO = EXTRACT(YEAR FROM CURRENT_DATE)
   AND P.MES = EXTRACT(MONTH FROM CURRENT_DATE);

CREATE VIEW V_DASH_SUPERVISOR_RESUMEN (VISTO_BUENO_MES, DEVUELTAS_MES, APROBADAS_MES, RECHAZADAS_MES, MONTO_APROBADO_MES, TASA_APROBACION, TASA_ANTERIOR, MONTO_APROBADO_ANTERIOR, MES_ANTERIOR, VARIACION_TASA, VARIACION_MONTO) AS
SELECT R.*,
       CAST(R.TASA_APROBACION - R.TASA_ANTERIOR AS NUMERIC(6,2))
         AS VARIACION_TASA,
       CASE WHEN R.MONTO_APROBADO_ANTERIOR > 0
            THEN CAST((R.MONTO_APROBADO_MES - R.MONTO_APROBADO_ANTERIOR)
                 * 100.0000 / R.MONTO_APROBADO_ANTERIOR AS NUMERIC(7,2)) END
         AS VARIACION_MONTO
  FROM (SELECT CAST(COALESCE(A.VISTO_BUENO, 0) AS INTEGER) AS VISTO_BUENO_MES,
               CAST(COALESCE(A.DEVUELTAS, 0) AS INTEGER) AS DEVUELTAS_MES,
               CAST(COALESCE(A.APROBADAS, 0) AS INTEGER) AS APROBADAS_MES,
               CAST(COALESCE(A.RECHAZADAS, 0) AS INTEGER) AS RECHAZADAS_MES,
               CAST(COALESCE(A.MONTO_APROBADO, 0) AS NUMERIC(18,2))
                 AS MONTO_APROBADO_MES,
               CAST(COALESCE(A.APROBADAS * 100.0000
                    / NULLIF(A.APROBADAS + A.RECHAZADAS, 0), 0) AS NUMERIC(5,2))
                 AS TASA_APROBACION,
               CAST(COALESCE(B.APROBADAS * 100.0000
                    / NULLIF(B.APROBADAS + B.RECHAZADAS, 0), 0) AS NUMERIC(5,2))
                 AS TASA_ANTERIOR,
               CAST(COALESCE(B.MONTO_APROBADO, 0) AS NUMERIC(18,2))
                 AS MONTO_APROBADO_ANTERIOR,
               P.MES_ANTERIOR
          FROM V_PERIODO_ACTUAL P
          LEFT JOIN V_DASH_PASOS_EQUIPO A
            ON A.ANIO = EXTRACT(YEAR FROM P.MES_DESDE)
           AND A.MES = EXTRACT(MONTH FROM P.MES_DESDE)
          LEFT JOIN V_DASH_PASOS_EQUIPO B
            ON B.ANIO = EXTRACT(YEAR FROM P.MES_ANTERIOR)
           AND B.MES = EXTRACT(MONTH FROM P.MES_ANTERIOR)) R;

CREATE VIEW V_REPORTE_DIA (PERIODO, FECHA, ANIO, MES, ESTADO, ASESOR_ID, ASESOR_NOMBRE, TIPO_TRABAJO_ID, TIPO_TRABAJO_NOMBRE, ELABORADA_POR, CANTIDAD, MONTO_TOTAL, APROBADAS, RECHAZADAS, MONTO_APROBADO, SUMA_DIAS_RESPUESTA, CON_RESPUESTA, ENVIADAS, MONTO_ENVIADO, DESCARTADAS, DEL_CLIENTE) AS
SELECT P.PERIODO, D.FECHA, D.ANIO, D.MES, D.ESTADO, D.ASESOR_ID,
       D.ASESOR_NOMBRE, D.TIPO_TRABAJO_ID, D.TIPO_TRABAJO_NOMBRE,
       D.ELABORADA_POR, D.CANTIDAD, D.MONTO_TOTAL, D.APROBADAS, D.RECHAZADAS,
       D.MONTO_APROBADO, D.SUMA_DIAS_RESPUESTA, D.CON_RESPUESTA,
       CAST(CASE WHEN D.ESTADO = 'enviada' THEN D.CANTIDAD ELSE 0 END
            AS INTEGER) AS ENVIADAS,
       CAST(CASE WHEN D.ESTADO = 'enviada' THEN D.MONTO_TOTAL ELSE 0 END
            AS NUMERIC(18,2)) AS MONTO_ENVIADO,
       CAST(CASE WHEN D.ESTADO = 'descartada' THEN D.CANTIDAD ELSE 0 END
            AS INTEGER) AS DESCARTADAS,
       (D.ESTADO IN ('enviada', 'descartada') OR D.APROBADAS > 0
        OR D.RECHAZADAS > 0) AS DEL_CLIENTE
  FROM V_REPORTE_PERIODO P
  JOIN V_COTIZACIONES_DIA D
    ON D.FECHA BETWEEN P.DESDE AND P.HASTA
   AND (P.USUARIO = 0 OR D.ASESOR_ID = P.USUARIO
        OR D.ELABORADA_POR = P.USUARIO);

CREATE VIEW V_REPORTE_RESUMEN (PERIODO, DESDE, HASTA, TOTAL, MONTO_TOTAL, APROBADAS, MONTO_APROBADO, RECHAZADAS, DESCARTADAS, RESPUESTA_MEDIA, TASA_APROBACION) AS
SELECT P.PERIODO, P.DESDE, P.HASTA,
       CAST(COALESCE(SUM(R.ENVIADAS), 0) AS INTEGER) AS TOTAL,
       CAST(COALESCE(SUM(R.MONTO_ENVIADO), 0) AS NUMERIC(18,2)) AS MONTO_TOTAL,
       CAST(COALESCE(SUM(R.APROBADAS), 0) AS INTEGER) AS APROBADAS,
       CAST(COALESCE(SUM(R.MONTO_APROBADO), 0) AS NUMERIC(18,2))
         AS MONTO_APROBADO,
       CAST(COALESCE(SUM(R.RECHAZADAS), 0) AS INTEGER) AS RECHAZADAS,
       CAST(COALESCE(SUM(R.DESCARTADAS), 0) AS INTEGER) AS DESCARTADAS,
       CAST(COALESCE(SUM(R.SUMA_DIAS_RESPUESTA)
            / NULLIF(SUM(R.CON_RESPUESTA), 0), 0) AS INTEGER)
         AS RESPUESTA_MEDIA,
       CAST(COALESCE(SUM(R.APROBADAS) * 100.0000
            / NULLIF(SUM(R.APROBADAS) + SUM(R.RECHAZADAS), 0), 0)
            AS NUMERIC(5,2)) AS TASA_APROBACION
  FROM V_REPORTE_PERIODO P
  LEFT JOIN V_REPORTE_DIA R ON R.PERIODO = P.PERIODO
 GROUP BY P.PERIODO, P.DESDE, P.HASTA;

CREATE VIEW V_REPORTE_ESTADO (ESTADO, ORDEN, CANTIDAD, MONTO) AS
SELECT R.ESTADO, CAST(E.ORDEN AS INTEGER) AS ORDEN,
       CAST(SUM(R.CANTIDAD) AS INTEGER) AS CANTIDAD,
       CAST(COALESCE(SUM(R.MONTO_TOTAL), 0) AS NUMERIC(18,2)) AS MONTO
  FROM V_REPORTE_DIA R
  JOIN ESTADOS_COTIZACION E ON E.CODIGO = R.ESTADO
 WHERE R.PERIODO = 'actual'
 GROUP BY R.ESTADO, E.ORDEN;

CREATE VIEW V_REPORTE_ASESOR (ASESOR_ID, ASESOR_NOMBRE, CANTIDAD, APROBADAS, RECHAZADAS, DESCARTADAS, MONTO_APROBADO, MONTO_TOTAL, TASA_APROBACION) AS
SELECT ASESOR_ID, ASESOR_NOMBRE,
       CAST(SUM(ENVIADAS) AS INTEGER) AS CANTIDAD,
       CAST(SUM(APROBADAS) AS INTEGER) AS APROBADAS,
       CAST(SUM(RECHAZADAS) AS INTEGER) AS RECHAZADAS,
       CAST(SUM(DESCARTADAS) AS INTEGER) AS DESCARTADAS,
       CAST(COALESCE(SUM(MONTO_APROBADO), 0) AS NUMERIC(18,2))
         AS MONTO_APROBADO,
       CAST(COALESCE(SUM(MONTO_ENVIADO), 0) AS NUMERIC(18,2)) AS MONTO_TOTAL,
       CAST(COALESCE(SUM(APROBADAS) * 100.0000
            / NULLIF(SUM(APROBADAS) + SUM(RECHAZADAS), 0), 0)
            AS NUMERIC(5,2)) AS TASA_APROBACION
  FROM V_REPORTE_DIA
 WHERE PERIODO = 'actual' AND DEL_CLIENTE
 GROUP BY ASESOR_ID, ASESOR_NOMBRE;

CREATE VIEW V_REPORTE_TIPO (TIPO_TRABAJO_ID, TIPO_TRABAJO_NOMBRE, CANTIDAD, APROBADAS, RECHAZADAS, DESCARTADAS, MONTO_APROBADO, MONTO_TOTAL, TASA_APROBACION) AS
SELECT TIPO_TRABAJO_ID, TIPO_TRABAJO_NOMBRE,
       CAST(SUM(ENVIADAS) AS INTEGER) AS CANTIDAD,
       CAST(SUM(APROBADAS) AS INTEGER) AS APROBADAS,
       CAST(SUM(RECHAZADAS) AS INTEGER) AS RECHAZADAS,
       CAST(SUM(DESCARTADAS) AS INTEGER) AS DESCARTADAS,
       CAST(COALESCE(SUM(MONTO_APROBADO), 0) AS NUMERIC(18,2))
         AS MONTO_APROBADO,
       CAST(COALESCE(SUM(MONTO_ENVIADO), 0) AS NUMERIC(18,2)) AS MONTO_TOTAL,
       CAST(COALESCE(SUM(APROBADAS) * 100.0000
            / NULLIF(SUM(APROBADAS) + SUM(RECHAZADAS), 0), 0)
            AS NUMERIC(5,2)) AS TASA_APROBACION
  FROM V_REPORTE_DIA
 WHERE PERIODO = 'actual' AND DEL_CLIENTE
 GROUP BY TIPO_TRABAJO_ID, TIPO_TRABAJO_NOMBRE;

CREATE VIEW V_REPORTE_MES (ANIO, MES, CANTIDAD, APROBADAS, RECHAZADAS, DESCARTADAS, MONTO_APROBADO, MONTO_TOTAL, TASA_APROBACION) AS
WITH RECURSIVE
P AS (
  SELECT DESDE, HASTA,
         CAST(EXTRACT(YEAR FROM DESDE) * 100 + EXTRACT(MONTH FROM DESDE)
           AS INTEGER) AS CLAVE_DESDE,
         CAST(EXTRACT(YEAR FROM HASTA) * 100 + EXTRACT(MONTH FROM HASTA)
           AS INTEGER) AS CLAVE_HASTA,
         CAST((EXTRACT(YEAR FROM HASTA) * 12 + EXTRACT(MONTH FROM HASTA))
            - (EXTRACT(YEAR FROM DESDE) * 12 + EXTRACT(MONTH FROM DESDE))
            AS INTEGER) AS SALTO
    FROM V_REPORTE_PERIODO
   WHERE PERIODO = 'actual'),
D AS (
  SELECT CAST(ANIO * 100 + MES AS INTEGER) AS CLAVE, ENVIADAS, APROBADAS,
         RECHAZADAS, DESCARTADAS, MONTO_APROBADO, MONTO_ENVIADO
    FROM V_REPORTE_DIA
   WHERE PERIODO = 'actual' AND DEL_CLIENTE),
L AS (
  SELECT CASE WHEN P.SALTO < 36 THEN P.CLAVE_DESDE
              ELSE (SELECT MIN(CLAVE) FROM D) END AS PRIMERA,
         CASE WHEN P.SALTO < 36 THEN P.CLAVE_HASTA
              ELSE (SELECT MAX(CLAVE) FROM D) END AS ULTIMA
    FROM P),
M (INICIO, ULTIMA) AS (
  SELECT CAST((PRIMERA / 100) || '-' || MOD(PRIMERA, 100) || '-01' AS DATE),
         ULTIMA
    FROM L
   WHERE PRIMERA IS NOT NULL
  UNION ALL
  SELECT DATEADD(1 MONTH TO INICIO), ULTIMA
    FROM M
   WHERE EXTRACT(YEAR FROM DATEADD(1 MONTH TO INICIO)) * 100
       + EXTRACT(MONTH FROM DATEADD(1 MONTH TO INICIO)) <= ULTIMA)
SELECT CAST(EXTRACT(YEAR FROM M.INICIO) AS INTEGER) AS ANIO,
       CAST(EXTRACT(MONTH FROM M.INICIO) AS INTEGER) AS MES,
       CAST(COALESCE(SUM(D.ENVIADAS), 0) AS INTEGER) AS CANTIDAD,
       CAST(COALESCE(SUM(D.APROBADAS), 0) AS INTEGER) AS APROBADAS,
       CAST(COALESCE(SUM(D.RECHAZADAS), 0) AS INTEGER) AS RECHAZADAS,
       CAST(COALESCE(SUM(D.DESCARTADAS), 0) AS INTEGER) AS DESCARTADAS,
       CAST(COALESCE(SUM(D.MONTO_APROBADO), 0) AS NUMERIC(18,2))
         AS MONTO_APROBADO,
       CAST(COALESCE(SUM(D.MONTO_ENVIADO), 0) AS NUMERIC(18,2)) AS MONTO_TOTAL,
       CAST(COALESCE(SUM(D.APROBADAS) * 100.0000
            / NULLIF(SUM(D.APROBADAS) + SUM(D.RECHAZADAS), 0), 0)
            AS NUMERIC(5,2)) AS TASA_APROBACION
  FROM M
  LEFT JOIN D ON D.CLAVE = EXTRACT(YEAR FROM M.INICIO) * 100
                         + EXTRACT(MONTH FROM M.INICIO)
 GROUP BY M.INICIO;

CREATE VIEW V_REPORTE_CLIENTE (CLIENTE_ID, CLIENTE_NOMBRE, ENVIADAS, ULTIMO_ENVIO, APROBADAS, RECHAZADAS, SIN_RESPUESTA, MONTO_SIN_RESPUESTA, EN_ESPERA, PORCENTAJE_SIN_RESPUESTA) AS
SELECT CLIENTE_ID, CLIENTE_NOMBRE,
       CAST(COUNT(*) AS INTEGER) AS ENVIADAS,
       MAX(FECHA_ENVIO) AS ULTIMO_ENVIO,
       CAST(SUM(CASE WHEN ESTADO = 'aprobada' THEN 1 ELSE 0 END) AS INTEGER)
         AS APROBADAS,
       CAST(SUM(CASE WHEN ESTADO = 'rechazada' THEN 1 ELSE 0 END) AS INTEGER)
         AS RECHAZADAS,
       CAST(SUM(CASE WHEN SIN_RESPUESTA THEN 1 ELSE 0 END) AS INTEGER)
         AS SIN_RESPUESTA,
       CAST(COALESCE(SUM(CASE WHEN SIN_RESPUESTA THEN MONTO_TOTAL END), 0)
            AS NUMERIC(18,2)) AS MONTO_SIN_RESPUESTA,
       CAST(SUM(CASE WHEN ESTADO NOT IN ('aprobada', 'rechazada')
                      AND NOT SIN_RESPUESTA THEN 1 ELSE 0 END) AS INTEGER)
         AS EN_ESPERA,
       CAST(SUM(CASE WHEN SIN_RESPUESTA THEN 1 ELSE 0 END) * 100.0000
            / COUNT(*) AS NUMERIC(5,2)) AS PORCENTAJE_SIN_RESPUESTA
  FROM (SELECT R.CLIENTE_ID, R.CLIENTE_NOMBRE, R.ESTADO, R.FECHA_ENVIO,
               R.MONTO_TOTAL,
               (R.ESTADO = 'descartada'
                OR (R.ESTADO = 'enviada'
                    AND DATEADD(COALESCE(R.DIAS_SIN_RESPUESTA, 0) DAY
                        TO R.FECHA_ENVIO) < CURRENT_TIMESTAMP))
                 AS SIN_RESPUESTA
          FROM V_REPORTE_PERIODO P
          JOIN V_CLIENTES_RESPUESTA R
            ON R.FECHA_ENVIO >= P.DESDE
           AND R.FECHA_ENVIO < DATEADD(1 DAY TO P.HASTA)
           AND (P.USUARIO = 0 OR R.ASESOR_ID = P.USUARIO
                OR R.ELABORADA_POR = P.USUARIO)
         WHERE P.PERIODO = 'actual')
 GROUP BY CLIENTE_ID, CLIENTE_NOMBRE;

CREATE VIEW V_COTIZACION_LINEAS (ID, COTIZACION_ID, TIPO, SUBTOTAL) AS
SELECT ID, COTIZACION_ID, TIPO,
       CAST(CANTIDAD * PRECIO_UNITARIO AS NUMERIC(15,2)) AS SUBTOTAL
  FROM VT_COTIZACION_DETALLE
 WHERE ACTIVO = TRUE;

CREATE VIEW V_COTIZACION_TOTALES (COTIZACION_ID, SUBTOTAL_MATERIALES, SUBTOTAL_MANO_OBRA, SUBTOTAL_MAQUINA, COSTO_TOTAL, MONTO_AJUSTE, MONTO_IMPUESTO, MONTO_TOTAL) AS
SELECT S.COTIZACION_ID, S.SUBTOTAL_MATERIALES, S.SUBTOTAL_MANO_OBRA,
       S.SUBTOTAL_MAQUINA, S.COSTO_TOTAL,
       CAST(S.COSTO_TOTAL * S.PORCENTAJE_AJUSTE / 100 AS NUMERIC(18,2))
         AS MONTO_AJUSTE,
       CAST(CAST((S.COSTO_TOTAL + S.COSTO_TOTAL * S.PORCENTAJE_AJUSTE / 100)
            AS NUMERIC(18,4)) * S.PORCENTAJE_IVA / 100 AS NUMERIC(18,2))
         AS MONTO_IMPUESTO,
       CAST(CAST((S.COSTO_TOTAL + S.COSTO_TOTAL * S.PORCENTAJE_AJUSTE / 100)
            AS NUMERIC(18,4))
          + CAST(CAST((S.COSTO_TOTAL + S.COSTO_TOTAL * S.PORCENTAJE_AJUSTE / 100)
            AS NUMERIC(18,4)) * S.PORCENTAJE_IVA / 100 AS NUMERIC(18,4))
            AS NUMERIC(18,2)) AS MONTO_TOTAL
  FROM (SELECT K.ID AS COTIZACION_ID, K.PORCENTAJE_AJUSTE, K.PORCENTAJE_IVA,
               CAST(COALESCE(SUM(CASE WHEN L.TIPO = 'material'
                    THEN L.SUBTOTAL END), 0) AS NUMERIC(18,2))
                 AS SUBTOTAL_MATERIALES,
               CAST(COALESCE(SUM(CASE WHEN L.TIPO = 'mano_obra'
                    THEN L.SUBTOTAL END), 0) AS NUMERIC(18,2))
                 AS SUBTOTAL_MANO_OBRA,
               CAST(COALESCE(SUM(CASE WHEN L.TIPO = 'maquina'
                    THEN L.SUBTOTAL END), 0) AS NUMERIC(18,2))
                 AS SUBTOTAL_MAQUINA,
               CAST(COALESCE(SUM(CASE WHEN L.TIPO IN ('material', 'mano_obra',
                    'maquina') THEN L.SUBTOTAL END), 0) AS NUMERIC(18,2))
                 AS COSTO_TOTAL
          FROM VT_COTIZACIONES K
          LEFT JOIN V_COTIZACION_LINEAS L ON L.COTIZACION_ID = K.ID
         GROUP BY K.ID, K.PORCENTAJE_AJUSTE, K.PORCENTAJE_IVA) S;

CREATE VIEW V_COTIZACIONES_LISTADO (ID, NUMERO, SOLICITUD_ID, CLIENTE_ID, TIPO_TRABAJO_ID, DESCRIPCION_TRABAJO, ELABORADA_POR, APROBADA_POR, ESTADO, SUBTOTAL_MATERIALES, SUBTOTAL_MANO_OBRA, SUBTOTAL_MAQUINA, COSTO_TOTAL, PORCENTAJE_AJUSTE, MOTIVO_AJUSTE, PORCENTAJE_IVA, MONTO_IMPUESTO, MONTO_TOTAL, MOTIVO_RECHAZO, FECHA_ELABORACION, FECHA_APROBACION, FECHA_ENVIO, FECHA_MODIFICACION, OBJVERSION, FORMA_PAGO, FORMA_PAGO_ID, PLAZO_ENTREGA_CANTIDAD, PLAZO_ENTREGA_UNIDAD, GARANTIA_CANTIDAD, GARANTIA_UNIDAD, ORDEN_COMPRA, FECHA_RECEPCION, CLIENTE_NOMBRE, ASESOR_ID, ASESOR_NOMBRE, ELABORADA_POR_NOMBRE, APROBADA_POR_NOMBRE, TIPO_TRABAJO_NOMBRE, DEVUELTA, DIAS_EN_ESTADO, DIAS_RESPUESTA, MONTO_AJUSTE) AS
SELECT K.ID, K.NUMERO, K.SOLICITUD_ID, K.CLIENTE_ID, K.TIPO_TRABAJO_ID,
       K.DESCRIPCION_TRABAJO, K.ELABORADA_POR, K.APROBADA_POR, K.ESTADO,
       K.SUBTOTAL_MATERIALES, K.SUBTOTAL_MANO_OBRA, K.SUBTOTAL_MAQUINA,
       K.COSTO_TOTAL, K.PORCENTAJE_AJUSTE, K.MOTIVO_AJUSTE, K.PORCENTAJE_IVA,
       K.MONTO_IMPUESTO, K.MONTO_TOTAL, K.MOTIVO_RECHAZO, K.FECHA_ELABORACION,
       K.FECHA_APROBACION, K.FECHA_ENVIO, K.FECHA_MODIFICACION, K.OBJVERSION,
       K.FORMA_PAGO, K.FORMA_PAGO_ID, K.PLAZO_ENTREGA_CANTIDAD,
       K.PLAZO_ENTREGA_UNIDAD, K.GARANTIA_CANTIDAD, K.GARANTIA_UNIDAD,
       K.ORDEN_COMPRA,
       V.FECHA_RECEPCION, V.CLIENTE_NOMBRE, V.ASESOR_ID, V.ASESOR_NOMBRE,
       V.ELABORADA_POR_NOMBRE, V.APROBADA_POR_NOMBRE, V.TIPO_TRABAJO_NOMBRE,
       V.DEVUELTA, V.DIAS_EN_ESTADO, V.DIAS_RESPUESTA,
       CAST(K.COSTO_TOTAL * K.PORCENTAJE_AJUSTE / 100 AS NUMERIC(18,2))
         AS MONTO_AJUSTE
  FROM VT_COTIZACIONES K
  JOIN V_COTIZACIONES V ON V.ID = K.ID;

CREATE VIEW V_COTIZACIONES_SIN_RESPUESTA (ID, NUMERO, SOLICITUD_ID, CLIENTE_ID, TIPO_TRABAJO_ID, DESCRIPCION_TRABAJO, ELABORADA_POR, APROBADA_POR, ESTADO, SUBTOTAL_MATERIALES, SUBTOTAL_MANO_OBRA, SUBTOTAL_MAQUINA, COSTO_TOTAL, PORCENTAJE_AJUSTE, MOTIVO_AJUSTE, PORCENTAJE_IVA, MONTO_IMPUESTO, MONTO_TOTAL, MOTIVO_RECHAZO, FECHA_ELABORACION, FECHA_APROBACION, FECHA_ENVIO, FECHA_MODIFICACION, OBJVERSION, FORMA_PAGO, FORMA_PAGO_ID, PLAZO_ENTREGA_CANTIDAD, PLAZO_ENTREGA_UNIDAD, GARANTIA_CANTIDAD, GARANTIA_UNIDAD, ORDEN_COMPRA, FECHA_RECEPCION, CLIENTE_NOMBRE, ASESOR_ID, ASESOR_NOMBRE, ELABORADA_POR_NOMBRE, APROBADA_POR_NOMBRE, TIPO_TRABAJO_NOMBRE, DEVUELTA, DIAS_EN_ESTADO, DIAS_RESPUESTA, MONTO_AJUSTE) AS
SELECT L.*
  FROM V_COTIZACIONES_LISTADO L
 CROSS JOIN (SELECT COALESCE(MAX(E.DIAS_SIN_RESPUESTA), 7) AS DIAS
               FROM EMPRESA E) P
 WHERE L.ESTADO = 'enviada'
   AND L.FECHA_ENVIO < DATEADD(-P.DIAS DAY TO CURRENT_TIMESTAMP);

CREATE VIEW V_CONTACTOS_BAJADA (ID, UUID_LOCAL, CLIENTE_ID, NOMBRE, AREA, TELEFONO, CORREO, PRINCIPAL, CONSENTIMIENTO_ESTADO, CONSENTIMIENTO_FECHA, CONSENTIMIENTO_VERSION, ANONIMIZADO, ACTIVO, FECHA_CREACION, OBJVERSION, CELULAR, FECHA_MODIFICACION, CLIENTE_UUID, CLIENTE_ACTIVO) AS
SELECT CC.ID, CC.UUID_LOCAL, CC.CLIENTE_ID, CC.NOMBRE, CC.AREA, CC.TELEFONO,
       CC.CORREO, CC.PRINCIPAL, CC.CONSENTIMIENTO_ESTADO,
       CC.CONSENTIMIENTO_FECHA, CC.CONSENTIMIENTO_VERSION, CC.ANONIMIZADO,
       CC.ACTIVO, CC.FECHA_CREACION, CC.OBJVERSION, CC.CELULAR,
       CC.FECHA_MODIFICACION, C.UUID_LOCAL AS CLIENTE_UUID,
       C.ACTIVO AS CLIENTE_ACTIVO
  FROM VT_CLIENTE_CONTACTOS CC
  JOIN CLIENTES C ON C.ID = CC.CLIENTE_ID;

COMMIT;

/* ---------------------------------------------------------------------------
   9. Permisos del rol del backend. Al quitar una vista se van sus permisos.
   --------------------------------------------------------------------------- */

GRANT SELECT ON ESTADOS_COTIZACION TO ROL_BACKEND;
GRANT SELECT ON ESTADOS_SOLICITUD TO ROL_BACKEND;
GRANT SELECT ON ESTADOS_CONSENTIMIENTO TO ROL_BACKEND;
GRANT SELECT ON ACCIONES_CONSENTIMIENTO TO ROL_BACKEND;
GRANT SELECT ON ORIGENES_REGISTRO TO ROL_BACKEND;
